update public.course_modules set title = 'Fondamentaux des réseaux', description = 'Tu poses ici le vocabulaire et les réflexes qui serviront dans tout le parcours : équipements, couches, encapsulation et lecture d’un trajet réseau réel. Critères de réussite : expliquer le rôle d’un commutateur, d’un routeur et d’une passerelle ; situer un protocole, une commande ou une panne dans la bonne couche ; raconter le voyage d’une requête web en citant ce qui change à chaque saut.'
