update public.course_modules set title = 'Adressage IPv4', description = 'Ce module transforme les bases IPv4 en vraie méthode de planification : lire, découper, puis attribuer des sous-réseaux adaptés à une organisation qui grandit. Critères de réussite : reconnaître une plage privée RFC 1918 ; choisir un préfixe cohérent pour un besoin donné ; produire un plan VLSM sans chevauchement avec une convention de passerelle claire.'
