update public.course_modules set title = 'Services réseau', description = 'Ce module montre comment le réseau rend un nom lisible, attribue une adresse, partage une sortie Internet et garde des journaux exploitables. Critères de réussite : diagnostiquer une panne DNS ou DHCP simple, expliquer une traduction NAT ou PAT à partir d’une table, et vérifier qu’un équipement d’infrastructure a une heure et une journalisation cohérentes.'
where id = 'e5593265-96cd-af22-796d-43f710a7270f' and title = 'Les services du réseau';
