update public.course_modules set title = 'Protocoles de transport et du web', description = 'Ce module t’apprend à lire les transports réseau et une conversation web réelle, des ports locaux jusqu’aux requêtes HTTP dans TLS. Critères de réussite : interpréter un port ou un service exposé, distinguer ce qu’UDP et ICMP racontent d’un incident, et lire une requête web avec son niveau de protection réel.'
where id = '164a6fca-6567-1fd3-2956-fe662b74b303' and title = 'Lire un échange TCP';
