update public.lessons set content = jsonb_set(content, '{blocks}', (content -> 'blocks') || '[{"type":"example","content":"Dans une maquette, PC-A (172.16.8.10/27) ne joint pas PC-B (172.16.8.40) alors que le routeur a une interface dans chaque sous-réseau. Avant de rien modifier, tu notes ce que tu observes, puis tu relis la configuration de PC-B : son masque est 255.255.255.0 au lieu de 255.255.255.224. PC-B croit donc que 172.16.8.10 se trouve sur son propre réseau : il l’appelle directement avec ARP au lieu de passer par sa passerelle, 172.16.8.33. Après correction du masque, le ping réussit, et show ip interface brief confirme que les deux interfaces du routeur sont up."},{"type":"resource","content":"Cisco Packet Tracer : télécharger et apprendre","url":"https://www.netacad.com/cisco-packet-tracer"},{"type":"resource","content":"Cisco Networking Academy : cours gratuits","url":"https://www.netacad.com/"}]'::jsonb)
where id = '4a008f9c-3624-a469-6392-224e0f72514f' and not exists (select 1 from jsonb_array_elements(content -> 'blocks') b where b ->> 'type' = 'resource');

on conflict (id) do nothing;

10.2.0.160/28 : hôtes 10.2.0.161 à 10.2.0.174', '10.2.0.160 est l’adresse réseau et 10.2.0.175 la diffusion. Si la convention est « première adresse utilisable », la passerelle est bien 10.2.0.161.', 'difficile', 7),
  ('0136df6f-437f-a34d-7086-bc844f2037df', '0e2c32fa-917b-b71f-bbf3-4cb4e1ad8fb5', 4, 'true_false', 'Les plages privées RFC 1918 incluent notamment 10.0.0.0/8 et 172.16.0.0/12.', 'Vrai : ce sont deux des trois grands espaces privés réservés aux réseaux internes, avec 192.168.0.0/16. Ils ne sont pas routés directement sur Internet.', 'facile', 7),
  ('b66830cb-1864-3861-7418-9914c49a5dc0', '312bbb74-ad53-ddc5-2a59-092e9f74cd50', 1, 'single_choice', 'Combien de bits contient une adresse IPv6 ?', 'Une adresse IPv6 contient 128 bits. C’est ce qui explique son écriture sur huit groupes hexadécimaux et l’immense espace disponible.', 'facile', 8),
  ('e91ddb3f-fdad-c972-c3a7-86e83179373b', '312bbb74-ad53-ddc5-2a59-092e9f74cd50', 2, 'multiple_choice', 'Quelles règles d’écriture IPv6 sont correctes ? (plusieurs réponses)', 'Les zéros de tête peuvent disparaître et :: ne peut servir qu’une seule fois. Le bloc 2001:db8::/32 est bien réservé aux exemples. En revanche, un /48 contient 65 536 réseaux /64, pas 256.', 'moyen', 8),
  ('788596c3-5a38-64fd-2681-1d22a0f215b5', '312bbb74-ad53-ddc5-2a59-092e9f74cd50', 3, 'single_choice', 'Quelle est la bonne forme compressée de 2001:0db8:0001:0012:0000:0000:0000:0034 ?', 'On enlève les zéros de tête, puis on remplace la plus longue suite de groupes nuls par un seul « :: » : 2001:db8:1:12::34. Les autres écritures sont fausses : deux « :: » rendent l’adresse invalide, 2001::db8:1:12:34 désigne une autre adresse, et 2001:db8:1:12:0:0:0:34 est la même adresse mais n’est pas compressée.', 'difficile', 7),
  ('138b10af-d83c-24e6-dbed-04fe8f5feec0', '312bbb74-ad53-ddc5-2a59-092e9f74cd50', 4, 'true_false', 'En IPv6, le fait de ne pas dépendre du NAT ne dispense pas d’un pare-feu.', 'Vrai : IPv6 facilite l’adressage de bout en bout, mais le contrôle d’accès reste indispensable. Le NAT ne doit jamais être confondu avec une politique de sécurité.', 'moyen', 7),
  ('91f4794a-a87c-aad7-aa3a-ba3d4ae5db68', '3afa7f12-31e2-2b13-d33b-65b9ceb55fa3', 1, 'single_choice', 'Quel préfixe correspond aux adresses link-local IPv6 ?', 'Les adresses link-local commencent par fe80::/10. Elles servent aux échanges sur le lien local, notamment avec la passerelle et NDP.', 'facile', 8),
  ('46668217-9e3b-daf5-00e9-877bef5200a8', '3afa7f12-31e2-2b13-d33b-65b9ceb55fa3', 2, 'multiple_choice', 'Quelles affirmations sur l’autoconfiguration IPv6 sont exactes ? (plusieurs réponses)', 'SLAAC, DHCPv6 et NDP sont bien trois briques centrales d’IPv6. En revanche, IPv6 n’a pas de broadcast général : il utilise le multicast pour atteindre des groupes précis.', 'moyen', 8),
  ('0d57e068-e534-d65f-6b9a-29fa8494326e', '3afa7f12-31e2-2b13-d33b-65b9ceb55fa3', 3, 'single_choice', 'Tu lis cette sortie :
inet6 2001:db8:1:20::23/64 scope global dynamic
inet6 fe80::b84d:12ff:fe34:5678/64 scope link
Quelle conclusion est la plus juste ?', 'Cette combinaison est normale : l’interface garde une adresse link-local et peut aussi avoir une adresse globale dans le /64 du LAN. Deux adresses IPv6 sur la même interface ne signalent pas une attaque à elles seules.', 'difficile', 7),
  ('61df17ea-cb62-f113-1f41-1aaa55d4b08d', '3afa7f12-31e2-2b13-d33b-65b9ceb55fa3', 4, 'true_false', 'Bloquer aveuglément ICMPv6 peut casser NDP et donc perturber le fonctionnement normal d’IPv6.', 'Vrai : NDP, la découverte de routeur et plusieurs mécanismes essentiels d’IPv6 s’appuient sur ICMPv6. Le filtrer sans discernement casse souvent le réseau.', 'moyen', 7),
  ('a606fcf1-ea56-072c-1931-f8875b0a0b67', 'be5cfba1-9bc8-941f-6747-b006af0e8208', 1, 'single_choice', 'Quel champ d’une trame Ethernet indique le protocole transporté, par exemple IPv4 ou ARP ?', 'L’EtherType identifie le contenu de la trame, par exemple 0x0800 pour IPv4 ou 0x0806 pour ARP. Le TTL appartient à IP, les ports source à TCP ou UDP, et le FCS sert seulement au contrôle d’erreur.', 'facile', 8),
  ('a1ee3b2c-011d-70d4-0b9d-0d75f44a534a', 'be5cfba1-9bc8-941f-6747-b006af0e8208', 2, 'true_false', 'Quand un commutateur reçoit une trame dont la destination MAC lui est inconnue, il la jette immédiatement.', 'Faux : il commence par apprendre la MAC source sur le port d’entrée, puis il inonde la trame sur les autres ports du même VLAN. Il ne peut pas encore la filtrer, justement parce qu’il ignore où se trouve la destination.', 'moyen', 8),
  ('3debdd4e-e683-a640-d101-aa62d1fb7e82', 'be5cfba1-9bc8-941f-6747-b006af0e8208', 3, 'multiple_choice', 'Que peux-tu conclure à partir de cet extrait ? Vlan 110, 0800.27aa.bb25 -> Fa0/3 et 0800.27aa.bb40 -> Fa0/9. Plusieurs réponses sont justes.', 'La table montre que deux sources ont été apprises dans le même VLAN sur deux ports distincts. Le commutateur peut donc transmettre directement entre elles. Rien n’indique des VLAN différents, et ces entrées sont créées par le commutateur lui-même, pas par le routeur.', 'difficile', 7),
  ('4f223159-bb73-5107-3b41-cfb1c58606e2', 'be5cfba1-9bc8-941f-6747-b006af0e8208', 4, 'single_choice', 'Pourquoi une requête ARP est-elle envoyée en diffusion dans un LAN ?', 'ARP sert à découvrir la MAC associée à une IPv4 locale. La diffusion vise tous les hôtes du VLAN pour que seul le bon réponde. DNS et TCP n’interviennent pas ici, et une table MAC vide n’est pas la cause : elle sera justement remplie pendant l’échange.', 'moyen', 7),
  ('09f04b83-e3e0-2305-32ea-c175093d39fa', '9b84376d-cc1b-9730-9c83-af92c873ed16', 1, 'single_choice', 'Quel énoncé décrit le mieux un port trunk ?', 'Un trunk transporte plusieurs VLAN entre commutateurs, routeurs ou équipements équivalents en ajoutant un tag 802.1Q aux trames, sauf souvent pour le VLAN natif. Un port access, lui, sert aux postes et reste sans tag.', 'facile', 8),
  ('79d6eced-5730-4039-0ff9-b7f31f93c27c', '9b84376d-cc1b-9730-9c83-af92c873ed16', 2, 'single_choice', 'Tu lis show interfaces trunk et vois Native vlan 1 sur SW1, mais Native vlan 199 sur SW2. Quel risque ou symptôme est le plus cohérent ?', 'Un VLAN natif incohérent provoque des comportements imprévisibles et fragilise l’isolation. Le trunk ne devient pas un port access, il ne fusionne pas les VLAN et il n’ajoute aucun routage par magie.', 'difficile', 8),
  ('fad8377a-f167-c01a-d6e8-5eedcdc7bacf', '9b84376d-cc1b-9730-9c83-af92c873ed16', 3, 'multiple_choice', 'Quelles bonnes pratiques réduisent les risques liés aux VLAN ? Plusieurs réponses sont justes.', 'Forcer les ports d’utilisateur en access, limiter les VLAN autorisés et isoler le VLAN natif réduisent fortement les erreurs et les attaques. En revanche, un VLAN seul ne filtre pas le trafic de couche 3 : il faut aussi du routage contrôlé et souvent des ACL.', 'moyen', 7),
  ('b26772df-5987-1bad-85a9-2ded9aaf641c', '9b84376d-cc1b-9730-9c83-af92c873ed16', 4, 'true_false', 'Deux postes dans deux VLAN différents peuvent communiquer directement sans équipement de couche 3.', 'Faux : ils sont dans deux domaines de diffusion distincts. Sans routeur ou commutateur de niveau 3 pour faire le relais, aucune communication IP normale ne traverse cette frontière logique.', 'moyen', 7),
  ('72062063-8acc-ee37-7749-441605b0a1cb', '7746315e-ff04-1c19-6f0d-b082ae3861da', 1, 'single_choice', 'Quelle route gagne si un paquet vers 10.2.8.130 correspond à 10.2.0.0/16, 10.2.8.0/24 et 0.0.0.0/0 ?', 'Le routeur applique la règle du plus long préfixe. La route /24 est plus spécifique que /16 et bien plus spécifique que /0. L’ordre de création n’est pas le critère décisif ici.', 'moyen', 8),
  ('9bc626f6-3ede-859a-26c2-87b13a48895b', '7746315e-ff04-1c19-6f0d-b082ae3861da', 2, 'true_false', 'Si le ping part bien du site A vers le site B, le site B saura forcément répondre.', 'Faux : le retour exige sa propre route. Une route correcte à l’aller ne garantit pas que le second routeur connaisse le chemin inverse, et c’est une cause très classique d’échec de ping.', 'moyen', 8),
  ('8802d529-314c-2091-3ec5-6a94d7497ed9', '7746315e-ff04-1c19-6f0d-b082ae3861da', 3, 'single_choice', 'Dans cet extrait, que signifie la lettre C devant 10.1.0.0/16 ?', 'Sur Cisco IOS, C signifie connected, donc un réseau directement relié à une interface active du routeur. Ce n’est ni une route dynamique ni une route importée d’un autre équipement.', 'facile', 7),
  ('0d82c0ef-bc97-93ce-22c7-2acfd098e928', '7746315e-ff04-1c19-6f0d-b082ae3861da', 4, 'multiple_choice', 'Quelles affirmations sur les routes statiques sont justes ? Plusieurs réponses sont correctes.', 'Les routes statiques sont très lisibles et conviennent bien aux petits réseaux ou à une sortie par défaut. En revanche, elles ne créent pas de route retour toutes seules et deviennent vite lourdes à maintenir quand la topologie grandit.', 'difficile', 7),
  ('da1ff491-da60-d05a-83ff-7701aaa911a3', 'f359c82b-29c3-6d7c-a03f-df7b7cb84dd7', 1, 'single_choice', 'Dans une architecture « routeur sur un bras », à quoi sert encapsulation dot1Q 110 sur Gi0/0.110 ?', 'La commande associe la sous-interface au tag 802.1Q du VLAN 110. Sans cette correspondance, le routeur ne sait pas quelle sous-interface doit traiter les trames reçues sur le trunk.', 'facile', 8),
  ('3d42e5be-2f14-5251-946d-9f50f73c817d', 'f359c82b-29c3-6d7c-a03f-df7b7cb84dd7', 2, 'true_false', 'Si deux postes sont dans des VLAN différents, ils peuvent communiquer sans passerelle tant qu’ils sont branchés sur le même commutateur.', 'Faux : le même commutateur ne suffit pas. Les VLAN créent des réseaux séparés et la communication IP entre eux exige un équipement de couche 3, donc une passerelle adaptée dans chaque VLAN.', 'moyen', 8),
  ('604ce4b4-cbd0-0592-9d35-7ebdbc9a799b', 'f359c82b-29c3-6d7c-a03f-df7b7cb84dd7', 3, 'single_choice', 'Quel symptôme est le plus cohérent si show ip interface brief affiche Gi0/0.110 down/down et Gi0/0.120 down/down ?', 'Si plusieurs sous-interfaces sont down/down, le problème vient souvent de l’interface physique porteuse ou du trunk. Le DNS et l’IPv6 n’expliquent pas l’état administratif et protocolaire de ces interfaces.', 'difficile', 7),
  ('4451c923-58ac-c195-ada1-f886900b520c', 'f359c82b-29c3-6d7c-a03f-df7b7cb84dd7', 4, 'multiple_choice', 'Quelles vérifications sont pertinentes quand deux VLAN ne se joignent pas ? Plusieurs réponses sont justes.', 'Le trunk, les passerelles et les identifiants dot1Q sont les trois vérifications majeures. En revanche, la table ARP n’a pas besoin d’être déjà complète avant le premier ping : elle se construit justement pendant les premiers échanges.', 'moyen', 7),
  ('9705ceb6-bb9b-95ff-8b1f-e5058a1347ba', '62643f09-3ef1-ac88-21cd-70469ed63638', 1, 'single_choice', 'Quel protocole utilise une métrique fondée sur le nombre de sauts, avec un maximum de 15 ?', 'RIP compte les sauts et considère 16 comme injoignable. OSPF utilise un coût de lien, BGP sert entre systèmes autonomes, et ARP ne fait pas de routage du tout.', 'facile', 8),
  ('1931201d-3c45-61b5-6fc2-6eb2f03cfcad', '62643f09-3ef1-ac88-21cd-70469ed63638', 2, 'single_choice', 'Si une même route existe en statique et en OSPF, laquelle est préférée par défaut ?', 'Par défaut, une route statique a une distance administrative de 1, contre 110 pour OSPF. Le routeur préfère donc la statique, sauf configuration particulière. Le caractère dynamique ne donne pas la priorité.', 'moyen', 8),
  ('133a2c0a-b5e5-815a-642b-4e834dadb735', '62643f09-3ef1-ac88-21cd-70469ed63638', 3, 'true_false', 'La commande passive-interface sert notamment à éviter qu’une interface côté LAN utilisateur forme un voisinage de routage inutile.', 'Vrai : rendre passive une interface empêche l’établissement de voisinages ou l’envoi d’annonces là où ce n’est pas nécessaire, tout en pouvant continuer à annoncer le réseau local selon le protocole et la configuration.', 'moyen', 7),
  ('be17ccae-250a-55f5-fa07-159c405b4fb8', '62643f09-3ef1-ac88-21cd-70469ed63638', 4, 'multiple_choice', 'Dans quels cas OSPF est-il souvent un meilleur choix que RIP ? Plusieurs réponses sont correctes.', 'OSPF est plus adapté aux réseaux plus riches en chemins, plus grands ou plus exigeants en convergence et en contrôle. La limite de 15 sauts est justement une faiblesse de RIP, pas un avantage pour choisir OSPF.', 'difficile', 7),
  ('c1868f20-dfb3-e5a9-62be-7c9485ac7e5b', '96f9246c-fd0f-9627-33ec-ff60cadbabc6', 1, 'single_choice', 'Quelle étape vient juste après le DHCP Offer dans la séquence DORA ?', 'Après l’offre, le client envoie un Request pour dire quelle adresse il accepte. L’Acknowledge vient seulement après, quand le serveur confirme le bail.', 'facile', 8),
  ('8c05818d-a917-17c2-9bd6-1eb69de66edc', '96f9246c-fd0f-9627-33ec-ff60cadbabc6', 2, 'true_false', 'Une adresse 169.254.22.11 indique souvent qu’un poste n’a pas obtenu de bail DHCP utilisable.', 'Vrai : cette plage APIPA apparaît souvent quand aucun serveur DHCP n’a répondu ou quand la réponse n’était pas exploitable. Ce n’est pas une adresse destinée à un accès normal à Internet.', 'moyen', 8),
  ('d985ad00-f20f-2698-c592-49cc66919213', '96f9246c-fd0f-9627-33ec-ff60cadbabc6', 3, 'multiple_choice', 'Quelles informations un serveur DHCP peut-il fournir à un client ? (plusieurs réponses)', 'DHCP distribue des paramètres réseau, pas des secrets d’administration. La tentation est de croire qu’il « configure tout », mais il ne doit jamais servir à exposer des mots de passe.', 'moyen', 7),
  ('e117536e-435f-5e3a-17ca-7654fdc3dff3', '96f9246c-fd0f-9627-33ec-ff60cadbabc6', 4, 'single_choice', 'Sur Cisco IOS, quelle commande relaye les requêtes DHCP d’un autre réseau vers le serveur ?', 'Sur IOS, ip helper-address relaie plusieurs diffusions utiles, dont DHCP. Les autres propositions ressemblent à des commandes plausibles, mais elles ne réalisent pas ce rôle.', 'difficile', 7),
  ('2d82809f-a7c1-fe67-fe3c-d2cb01016126', '49b1566d-968f-880c-5ad1-0ed704f01b03', 1, 'single_choice', 'Quel mécanisme permet à plusieurs postes privés de partager une seule adresse IPv4 publique grâce aux ports source ?', 'PAT, aussi appelé surcharge, distingue les flux avec des ports différents. NAT statique garde une correspondance fixe et ne sert pas à mutualiser massivement une seule adresse.', 'facile', 8),
  ('6f1a4d0f-597a-aa90-37d4-89c0904ead66', '49b1566d-968f-880c-5ad1-0ed704f01b03', 2, 'single_choice', 'Dans la terminologie Cisco, 10.2.1.20 est quoi si c’est l’adresse privée du poste dans le LAN ?', 'Inside local désigne l’adresse privée vue à l’intérieur du réseau. Inside global est l’adresse publique qui représente ce client vers l’extérieur.', 'moyen', 8),
  ('30712add-a32c-b8bc-d8fa-03994b60f2ea', '49b1566d-968f-880c-5ad1-0ed704f01b03', 3, 'true_false', 'Le fait d’utiliser NAT suffit à remplacer une politique de pare-feu.', 'Faux : NAT change des adresses, mais il n’exprime pas à lui seul une politique de sécurité complète. Un pare-feu décide quels flux sont autorisés, refusés et journalisés.', 'moyen', 7),
  ('e4257fbe-971a-849c-520c-c64be68d9dfc', '49b1566d-968f-880c-5ad1-0ed704f01b03', 4, 'multiple_choice', 'Quelles actions sont nécessaires pour un PAT simple sur Cisco IOS ? (plusieurs réponses)', 'L’ACL, les rôles inside or outside et le mot-clé overload sont indispensables dans cet exemple. Un DNS public peut être utile ailleurs, mais il n’est pas requis pour que PAT fonctionne.', 'difficile', 7),
  ('8a6de883-15d5-a7e9-8367-e7162e218676', '24eb8377-39df-51a5-bc8f-5fbe51603147', 1, 'single_choice', 'Pourquoi un décalage de quelques minutes entre deux équipements est-il gênant pendant un incident ?', 'Le trafic peut continuer à circuler, mais les journaux ne racontent plus la même chronologie. On perd alors la capacité à relier la cause, l’effet et la correction dans le bon ordre.', 'facile', 8),
  ('8e7d3562-49c8-0c95-056c-2cbbe083d927', '24eb8377-39df-51a5-bc8f-5fbe51603147', 2, 'single_choice', 'Quel protocole centralise souvent des journaux applicatifs et réseau via UDP 514 ?', 'Syslog est le protocole classique de centralisation des journaux. SNMP sert plutôt aux états et compteurs, ARP à la résolution locale et OSPF au routage.', 'moyen', 8),
  ('40e17a0f-9c26-b5e0-32d5-3ae4310c393d', '24eb8377-39df-51a5-bc8f-5fbe51603147', 3, 'multiple_choice', 'Quelles bonnes pratiques renforcent un service d’infrastructure sain ? (plusieurs réponses)', 'Les trois premières pratiques améliorent la cohérence et la sécurité. Régler l’heure à la main est tentant quand on débute, mais cela crée vite plus d’écarts et d’erreurs qu’autre chose.', 'moyen', 7),
  ('d42fed1d-2220-5bdf-a8a5-fe111bca6a27', '24eb8377-39df-51a5-bc8f-5fbe51603147', 4, 'true_false', 'Un certificat ou une authentification forte peut échouer si l’horloge de la machine est trop décalée.', 'Vrai : beaucoup de mécanismes de sécurité dépendent d’une notion de temps fiable. Une machine trop en retard ou trop en avance peut considérer un certificat comme expiré ou pas encore valide.', 'difficile', 7),
  ('2a02373a-0f09-14be-96a8-599b75768e31', '42aebbff-887a-e341-a072-e38e3ed974b1', 1, 'single_choice', 'Quelle plage correspond aux ports dynamiques ou éphémères ?', 'La plage 49152 à 65535 est celle que l’on voit souvent pour les ports source temporaires côté client. Les autres plages ont d’autres usages, et la dernière n’existe même pas en TCP ou UDP.', 'facile', 8),
  ('de2c1c4c-8172-474b-642d-14b9f51bbb42', '42aebbff-887a-e341-a072-e38e3ed974b1', 2, 'multiple_choice', 'Parmi ces services, lesquels sont les variantes chiffrées ou plus sûres par rapport à une version en clair ? (plusieurs réponses)', 'HTTPS, SSH et IMAPS apportent une protection de transport ou d’authentification par rapport aux versions en clair. FTP sur 21 n’est pas la version sûre de SFTP : ce sont deux protocoles différents.', 'moyen', 8),
  ('dc4d0925-007b-df01-1e0d-b341aa87ec2a', '42aebbff-887a-e341-a072-e38e3ed974b1', 3, 'single_choice', 'Dans la sortie suivante, quel port correspond au service NTP ? « udp   UNCONN 0.0.0.0:123  0.0.0.0:* »', 'Le port 123 est celui de NTP. Les autres valeurs sont plausibles parce qu’elles correspondent à des services courants, mais elles ne servent pas à la synchronisation de l’heure.', 'moyen', 7),
  ('f576520a-5cd4-638e-a233-5beafce97b0e', '42aebbff-887a-e341-a072-e38e3ed974b1', 4, 'true_false', 'Un port source client comme 53000 indique forcément qu’un service permanent écoute sur ce port côté serveur.', 'Faux : un port source élevé est souvent un port temporaire choisi par le client pour une session donnée. Le service serveur, lui, écoute généralement sur un port bien défini, comme 443 pour HTTPS.', 'difficile', 7),
  ('5cc18f32-2eb0-ebf6-6912-aef6440eaf78', 'b5663c5b-5b0a-33db-b416-ba4d9f697bbb', 1, 'single_choice', 'Quel énoncé décrit le mieux UDP ?', 'UDP reste volontairement minimal : pas de handshake, pas d’accusé automatique, pas d’ordre garanti. C’est justement ce qui le rend utile pour des usages sensibles à la latence.', 'facile', 8),
  ('4222c4b3-c42a-b11b-5fb9-418e17bbc4a4', 'b5663c5b-5b0a-33db-b416-ba4d9f697bbb', 2, 'single_choice', 'Quel message ICMP permet à traceroute d’afficher les routeurs intermédiaires ?', 'Traceroute envoie des paquets avec un TTL croissant. Quand un routeur le décrémente à zéro, il renvoie un message ICMP time exceeded, ce qui révèle son adresse.', 'moyen', 8),
  ('2999780a-c439-6050-f2d7-7cd51da8ab7e', 'b5663c5b-5b0a-33db-b416-ba4d9f697bbb', 3, 'true_false', 'Bloquer tout ICMP est toujours une bonne pratique de sécurité.', 'Faux : certains messages ICMP sont nécessaires au diagnostic et au bon fonctionnement du réseau, surtout en IPv6. Le bon réflexe consiste à filtrer intelligemment, pas à supprimer aveuglément.', 'moyen', 7),
  ('60767b49-f287-35a0-b084-0684533c64cf', 'b5663c5b-5b0a-33db-b416-ba4d9f697bbb', 4, 'single_choice', 'Un ping indique « 4 envoyés, 3 reçus, 25% de perte ». Quelle lecture est la plus juste ?', 'Une perte de 25 % signifie qu’une partie des paquets passe encore. C’est souvent suffisant pour expliquer une application dégradée, mais pas pour conclure à une coupure totale ou à la disparition de la machine.', 'difficile', 7),
  ('df44a511-e81e-19ab-8115-4b6444174e0e', '06fd1ca4-a0c9-cf23-2141-a1c40f4fd9a1', 1, 'single_choice', 'Que protège principalement TLS dans une session HTTPS ?', 'TLS protège surtout la confidentialité et l’intégrité des données en transit, ainsi que l’authentification du serveur via son certificat. Il ne garantit pas que l’application elle-même soit sans faille.', 'facile', 8),
  ('2797dd06-483f-39a2-05fd-318366a7d95e', '06fd1ca4-a0c9-cf23-2141-a1c40f4fd9a1', 2, 'single_choice', 'Quelle famille de codes HTTP correspond en général à une erreur côté client ?', 'Les 4xx signalent que le serveur a compris la requête mais qu’il ne peut pas l’accepter telle quelle, par exemple 401, 403 ou 404. Les 5xx concernent plutôt des erreurs côté serveur.', 'moyen', 8),
  ('b9417118-fc01-6e31-436c-0669733e37a3', '06fd1ca4-a0c9-cf23-2141-a1c40f4fd9a1', 3, 'multiple_choice', 'Quels attributs renforcent un cookie de session ? (plusieurs réponses)', 'Secure, HttpOnly et SameSite répondent chacun à un risque fréquent. « Public » semble plausible si l’on pense aux caches web, mais ce n’est pas un attribut de durcissement de cookie.', 'moyen', 7),
  ('6443b4da-e8d6-e7b2-3bc4-c067e8507077', '06fd1ca4-a0c9-cf23-2141-a1c40f4fd9a1', 4, 'true_false', 'Placer un jeton secret dans l’URL devient sans risque dès lors que le site utilise HTTPS.', 'Faux : HTTPS protège le transport, mais l’URL peut encore être copiée dans l’historique, des journaux, des proxys ou un en-tête Referer. Une donnée sensible n’a pas sa place dans une URL.', 'difficile', 7),
  ('4c742ed7-066d-be50-7bc4-bb479a27b936', 'ee5edad9-3b4c-6632-0def-47c2d8d8452e', 1, 'single_choice', 'Quel énoncé décrit correctement le fonctionnement d’une ACL Cisco ?', 'Cisco lit l’ACL ligne par ligne et s’arrête dès qu’une règle correspond. Il n’existe pas de « règle la plus précise » calculée à la fin, et le refus implicite final bloque tout ce qui n’a pas été autorisé.', 'facile', 8),
  ('e2d2df24-d666-8d20-172f-0cf16d5954b0', 'ee5edad9-3b4c-6632-0def-47c2d8d8452e', 2, 'true_false', 'Pour le réseau 10.3.130.0/24, le wildcard correct dans une ACL Cisco est 0.0.0.255.', 'C’est vrai : le masque 255.255.255.0 devient 0.0.0.255 dans une ACL. L’erreur tentante consiste à recopier le masque réseau tel quel, ce qui change complètement la portée de la règle.', 'moyen', 8),
  ('3b0f389a-d23b-37af-bb9b-cc07b2a43d58', 'ee5edad9-3b4c-6632-0def-47c2d8d8452e', 3, 'multiple_choice', 'Tu dois bloquer les invités vers l’administration, sans empêcher leur sortie Internet. Quelles décisions sont pertinentes ? (plusieurs réponses)', 'Une ACL étendue permet de viser précisément la source et la destination, puis les compteurs confirment le résultat. Retirer tout « permit » final couperait aussi les autres flux légitimes à cause du refus implicite.', 'difficile', 7),
  ('f42a4e3f-6db4-1ccf-6d83-3e7e497d0b8c', 'ee5edad9-3b4c-6632-0def-47c2d8d8452e', 4, 'single_choice', 'Lis cet extrait : « 10 deny ip 10.3.130.0 0.0.0.255 10.3.120.0 0.0.0.255 (14 matches) » puis « 20 permit ip any any (126 matches) ». Que comprends-tu ?', 'Le compteur du « deny » montre des tentatives bloquées vers l’administration, tandis que le compteur du « permit ip any any » prouve que les autres flux passent encore. C’est précisément le comportement attendu ici.', 'moyen', 7),
  ('c2107591-5b18-9eba-712d-057f7f69d900', '8bc2256a-16cc-4de8-2668-01e6ddd93546', 1, 'single_choice', 'Quel est le rôle principal d’une DMZ ?', 'La DMZ accueille les services visibles depuis l’extérieur, mais avec des règles strictes vers l’intérieur. L’erreur tentante est d’y mettre des postes sensibles, alors qu’elle est justement plus exposée que le LAN.', 'facile', 8),
  ('beee2781-cbbc-d0f7-e03a-7f96dd8c1ac6', '8bc2256a-16cc-4de8-2668-01e6ddd93546', 2, 'true_false', 'Un VLAN suffit à lui seul pour garantir qu’un serveur est isolé du reste du réseau.', 'C’est faux : un VLAN sépare les domaines de diffusion, pas la politique de sécurité complète. Sans routage filtré, ACL ou pare-feu, le trafic peut encore circuler entre réseaux logiques.', 'moyen', 8),
  ('65c18d20-6b9f-17ff-03b7-eb1cbe25ff20', '8bc2256a-16cc-4de8-2668-01e6ddd93546', 3, 'multiple_choice', 'Dans une matrice de flux saine, quelles décisions sont cohérentes ? (plusieurs réponses)', 'Le web public doit parfois être publié, et l’administration doit pouvoir maintenir les serveurs. En revanche, laisser les invités parler à l’administration détruit précisément l’objectif du cloisonnement.', 'difficile', 7),
  ('acb93e21-6b6c-614d-1423-85fa2c100dfa', '8bc2256a-16cc-4de8-2668-01e6ddd93546', 4, 'single_choice', 'Tu lis : « 20 deny ip 172.16.10.0 0.0.0.255 10.1.110.0 0.0.0.255 (3 matches) ». Quelle conclusion est la plus juste ?', 'Le compteur indique bien des paquets issus de la DMZ vers le LAN qui ont été stoppés. C’est précisément un signe que la segmentation joue son rôle, même si le nombre de tentatives reste faible.', 'moyen', 7),
  ('7ff4e8bf-7dda-4996-2ad7-dd9d6d3b87bf', '59c3580e-5d5e-257e-23e5-a8096f3d4f36', 1, 'single_choice', 'Quel mode de sécurité faut-il proscrire sur un Wi-Fi moderne ?', 'WEP est cassé depuis longtemps et ne doit plus être utilisé. Le piège serait de le conserver pour de vieux équipements, alors qu’il affaiblit tout le réseau sans réelle protection.', 'facile', 8),
  ('01cc0997-9429-edc1-e70d-093495189bd0', '59c3580e-5d5e-257e-23e5-a8096f3d4f36', 2, 'true_false', 'Cacher le SSID est une mesure suffisante pour protéger un réseau Wi-Fi d’entreprise.', 'C’est faux : un client déjà associé révèle rapidement le nom du réseau, et le chiffrement reste l’élément essentiel. Un SSID caché peut même compliquer le support sans apporter de vraie sécurité.', 'moyen', 8),
  ('85dae33b-9d45-f21b-3895-4560a1864894', '59c3580e-5d5e-257e-23e5-a8096f3d4f36', 3, 'multiple_choice', 'Quelles mesures de durcissement sont pertinentes sur un commutateur ou un routeur d’accès ? (plusieurs réponses)', 'SSH, les secrets robustes et un VLAN de gestion dédié réduisent fortement la surface d’attaque. Garder des ports inutilisés actifs, au contraire, offre des points d’entrée faciles et peu justifiés.', 'moyen', 7),
  ('e61b981f-448f-97e8-31c5-6f5f4266f21e', '59c3580e-5d5e-257e-23e5-a8096f3d4f36', 4, 'single_choice', 'Tu lis « transport input ssh » sous « line vty 0 4 ». Que signifie cette ligne ?', 'Cette commande restreint les lignes VTY aux connexions SSH. Elle ne concerne pas directement le Wi-Fi des clients, mais l’administration de l’équipement lui-même.', 'difficile', 7),
  ('829e5722-1e4b-e505-0965-9da769112711', '1f39b752-7d14-1b62-2dd9-a974e809442c', 1, 'single_choice', 'Quel ordre de test est le plus logique au début d’un dépannage poste client ?', 'On part du plus proche au plus lointain pour isoler rapidement la zone en panne. Commencer par le nom DNS ou un service lointain masque souvent un problème beaucoup plus local.', 'facile', 8),
  ('06c1f5cd-7970-9510-80ab-18c6da554299', '1f39b752-7d14-1b62-2dd9-a974e809442c', 2, 'true_false', 'Si « ping 1.1.1.1 » répond mais que « nslookup compta.atlas.example » échoue, le problème le plus probable n’est pas le routage.', 'C’est vrai : le chemin IP vers l’extérieur fonctionne déjà. Le symptôme pointe plutôt vers la résolution de nom, un enregistrement absent, ou un mauvais serveur DNS configuré.', 'moyen', 8),
  ('479f9ecd-d45a-8681-b5bc-2b5e88a9a545', '1f39b752-7d14-1b62-2dd9-a974e809442c', 3, 'multiple_choice', 'Quelles pratiques améliorent vraiment le dépannage ? (plusieurs réponses)', 'Un dépannage utile produit des preuves. Changer plusieurs choses à la fois empêche de savoir laquelle a eu un effet, et rend le retour arrière plus difficile en cas d’erreur.', 'moyen', 7),
  ('062c9c43-f4c4-19bb-c098-7eef966e24a4', '1f39b752-7d14-1b62-2dd9-a974e809442c', 4, 'single_choice', 'Lis ce « tracert » : saut 1 = 192.168.10.1, saut 2 = 10.2.0.1, puis timeouts. Quelle conclusion est la plus prudente ?', 'Le poste atteint clairement sa passerelle et un routeur amont. Le problème n’est donc plus au niveau du lien local immédiat. Le DNS peut être concerné dans d’autres cas, mais pas ce que prouve cet extrait.', 'difficile', 7),
  ('375dcafa-13f4-75e3-0b38-e412d80a55ca', 'fe952f84-3d47-b079-74d0-27ec375143cc', 1, 'single_choice', 'Que signifie « administratively down/down » dans « show ip interface brief » ?', 'Cet état signifie que l’interface est coupée par commande, souvent avec « shutdown ». Le piège classique consiste à chercher une panne physique alors que l’équipement lui-même interdit déjà l’activation du port.', 'facile', 8),
  ('5f6f8c15-3197-e13d-5d82-496d911b6cbb', 'fe952f84-3d47-b079-74d0-27ec375143cc', 2, 'true_false', 'Si un VLAN manque dans « show interfaces trunk », des postes de ce VLAN peuvent échouer même si « show vlan brief » semble correct.', 'C’est vrai : un port access peut être bien placé dans le bon VLAN sur un switch, mais si le trunk n’autorise pas ce VLAN jusqu’au routeur ou au switch voisin, le trafic s’arrête quand même.', 'moyen', 8),
  ('9b7a18c3-1003-6d9e-4743-332189f21908', 'fe952f84-3d47-b079-74d0-27ec375143cc', 3, 'multiple_choice', 'Quelles commandes sont directement utiles pour comprendre un problème de segmentation sur Cisco ? (plusieurs réponses)', 'Les trois commandes montrent l’état du port, l’appartenance VLAN et les VLAN réellement transportés. « copy running-config startup-config » est important après correction, mais n’explique pas la panne initiale.', 'moyen', 7),
  ('b3e531b6-c029-fd71-cdfa-3845dac3d0c8', 'fe952f84-3d47-b079-74d0-27ec375143cc', 4, 'single_choice', 'Tu lis « Vlans allowed on trunk : 110,120,199 » alors que le service invité est en VLAN 130. Quelle hypothèse est la meilleure ?', 'Le lien transporte explicitement 110, 120 et 199, pas 130. Le problème est donc très probablement la liste des VLAN autorisés sur le trunk, pas un souci DNS ou de routage global.', 'difficile', 7),
  ('8e546df9-8c5b-eba2-7f99-86b043efe1f9', 'f658d565-fa56-5be9-a4e3-40967faf3dee', 1, 'single_choice', 'Où s’exécute Cisco Packet Tracer ?', 'Packet Tracer est un logiciel installé sur ton ordinateur. CyberPingo ne l’exécute pas et ne lit pas tes fichiers .pkt : la plateforme fournit le sujet, la topologie et le guide, puis valide les résultats que tu saisis.', 'facile', 8),
  ('43cc5c23-8477-fa94-79b8-e666a21c2e20', 'f658d565-fa56-5be9-a4e3-40967faf3dee', 2, 'true_false', 'Sans Packet Tracer, tu ne peux pas valider les tâches d’un laboratoire Packet Tracer de CyberPingo.', 'Faux : les calculs du laboratoire se valident dans CyberPingo, avec ou sans le logiciel. Packet Tracer sert à pratiquer et à tester ton plan, il n’est pas une condition de validation.', 'moyen', 8),
  ('f654598c-66f8-0f77-1c74-66d5911d1149', 'f658d565-fa56-5be9-a4e3-40967faf3dee', 3, 'single_choice', 'Quelle commande IOS affiche une ligne par interface avec son adresse IP et son état, après une configuration ?', 'show ip interface brief résume l’adresse, l’état et le protocole de chaque interface : c’est la vérification la plus rapide. show running-config affiche toute la configuration, show version le matériel et le logiciel, show clock l’heure.', 'moyen', 7),
  ('b090b65f-7dad-8432-b38f-a299d38721a7', 'f658d565-fa56-5be9-a4e3-40967faf3dee', 4, 'single_choice', 'Dans Packet Tracer, un ping échoue entre deux sous-réseaux reliés par un routeur. Que vérifies-tu en premier ?', 'Un ping entre sous-réseaux traverse le routeur : on vérifie d’abord le masque et la passerelle des PC, puis l’état des interfaces avec show ip interface brief. Réinstaller le logiciel ou changer l’apparence des câbles n’a aucun effet sur la configuration.', 'difficile', 7),
  ('dac28d28-f123-6c1c-68fb-b9b3b95bba48', '5b8ecbe9-5b2e-204d-20a4-e67707b9a909', 1, 'single_choice', 'Quel élément ne doit jamais apparaître en clair dans une documentation réseau partagée ?', 'Les mots de passe doivent rester dans un coffre ou un gestionnaire de secrets, jamais dans un schéma ou un tableau diffusé à plusieurs personnes. Les autres éléments servent justement à comprendre et exploiter le réseau.', 'facile', 8),
  ('21a57c69-1323-fe1d-9aa5-e867c3baf85a', '5b8ecbe9-5b2e-204d-20a4-e67707b9a909', 2, 'true_false', 'Un schéma physique et un schéma logique décrivent exactement la même chose, il suffit donc d’en garder un seul.', 'C’est faux : le schéma physique décrit les branchements et emplacements, tandis que le schéma logique décrit réseaux, VLAN, routes et zones. Supprimer l’un des deux fait perdre une partie essentielle du contexte.', 'moyen', 8),
  ('0a8cb7f7-90d9-7c6b-89ba-22e90ed8984e', '5b8ecbe9-5b2e-204d-20a4-e67707b9a909', 3, 'multiple_choice', 'Quelles informations appartiennent à une documentation réseau utile ? (plusieurs réponses)', 'Le plan d’adressage, les VLAN et l’historique des changements permettent d’exploiter et de dépanner. Les secrets en clair, eux, transforment la documentation en fuite potentielle et doivent être exclus.', 'moyen', 7),
  ('ed9e0a76-17c0-1877-7ec6-08c66d3ff713', '5b8ecbe9-5b2e-204d-20a4-e67707b9a909', 4, 'single_choice', 'Quel compte rendu d’incident est le plus exploitable ?', 'Cette formulation donne le symptôme, la cause, la correction et la méthode de vérification. Les autres phrases sont trop vagues : elles n’aident ni une passation, ni un audit, ni un dépannage futur.', 'difficile', 7)
on conflict (id) do nothing;

on conflict (id) do nothing;

update public.courses c set estimated_duration = least(10000, s.total)
from (select course_id, sum(duration_minutes)::integer as total from public.lessons group by course_id) s
where c.id = 'c9468857-0122-856c-b60f-5c05e13778a7' and s.course_id = c.id and c.estimated_duration < s.total;

update public.courses set short_description = 'De l’adressage IPv4 et IPv6 aux VLAN, au routage, aux services et au diagnostic : un parcours complet pour comprendre un réseau, le configurer en simulation et le dépanner.', description = 'Ce parcours t’apprend à concevoir un petit réseau, à le configurer dans un simulateur gratuit, à expliquer les échanges entre équipements et à diagnostiquer les pannes les plus fréquentes. Dix modules progressifs couvrent les fondamentaux, l’adressage IPv4 et IPv6, la commutation Ethernet et les VLAN, le routage, les services (DNS, DHCP, NAT, NTP), les protocoles, la lecture de captures, la sécurité réseau, le diagnostic et la documentation.

Chaque leçon propose un cours détaillé, des exemples corrigés et un quiz avec correction. Trois travaux pratiques guidés, un incident à diagnostiquer et un projet final te font manipuler ce que tu apprends, avec des critères de réussite vérifiés par la plateforme.

Compétences visées : calculer un plan d’adressage, configurer une topologie, comprendre les échanges entre équipements, segmenter un réseau, diagnostiquer une panne, documenter une configuration.

Aucun prérequis : un ordinateur suffit. Cisco Packet Tracer et Wireshark sont gratuits. Les vidéos sont en préparation : chaque leçon indique clairement quand la sienne n’est pas encore disponible, et le cours écrit couvre déjà l’essentiel.'
where id = 'c9468857-0122-856c-b60f-5c05e13778a7' and short_description = 'Comprendre comment circulent les données pour mieux les protéger.' and description = 'DNS, ports, protocoles et modèle OSI : comprendre comment circulent les données pour repérer ce qui cloche et mieux les protéger.';

