  ('96f9246c-fd0f-9627-33ec-ff60cadbabc6', 'c9468857-0122-856c-b60f-5c05e13778a7', 'e5593265-96cd-af22-796d-43f710a7270f', 'e252b6c7-6646-fa7c-0318-dc4468253d8a', 'Quiz : DHCP', 70, 2),
