  ('ee5edad9-3b4c-6632-0def-47c2d8d8452e', 'c9468857-0122-856c-b60f-5c05e13778a7', '8146a83f-99b3-127a-9c1b-15725f88fda9', '30e93a35-47bd-51e0-6655-6bc990a03951', 'Quiz : ACL réseau', 70, 1),
  ('8bc2256a-16cc-4de8-2668-01e6ddd93546', 'c9468857-0122-856c-b60f-5c05e13778a7', '8146a83f-99b3-127a-9c1b-15725f88fda9', '3b3977f9-35da-5c11-82f2-26f6084881d1', 'Quiz : segmentation et DMZ', 70, 2),
  ('59c3580e-5d5e-257e-23e5-a8096f3d4f36', 'c9468857-0122-856c-b60f-5c05e13778a7', '8146a83f-99b3-127a-9c1b-15725f88fda9', 'cc077a0c-1cda-e187-2be3-338cf896f030', 'Quiz : sécurité Wi-Fi et durcissement', 70, 3),
  ('1f39b752-7d14-1b62-2dd9-a974e809442c', 'c9468857-0122-856c-b60f-5c05e13778a7', 'c786284d-9d45-cd49-36e8-a6567f32ad58', 'dc198c8e-24c1-f84c-d5cf-2fb3de66b1cb', 'Quiz : méthode de dépannage', 70, 1),
