insert into public.quiz_questions (id, quiz_id, position, question_type, prompt, explanation, difficulty, xp_reward) values
  ('6923c730-ce83-c611-13ca-47ac2d8a44a3', 'fd777393-b486-4c79-8b81-67f2a1409bdb', 1, 'single_choice', 'Quel équipement relie deux réseaux différents et choisit le chemin des paquets d’après leur adresse IP ?', 'C’est le rôle du routeur : il lit l’adresse IP de destination et choisit la sortie. Le commutateur et le point d’accès restent dans un seul réseau et s’appuient sur les adresses MAC ; la carte réseau est l’interface d’une machine, elle ne relie rien d’autre.', 'facile', 8),
  ('03c99cfd-0c91-c9ea-052f-11ca0f49fc79', 'fd777393-b486-4c79-8b81-67f2a1409bdb', 2, 'true_false', 'Dans une topologie en étoile, la rupture du câble d’un seul poste coupe tout le réseau.', 'Faux : seul ce poste est isolé, les autres continuent de communiquer, ce qui est un avantage de l’étoile. En revanche, la panne de l’équipement central, elle, coupe tout le monde.', 'moyen', 8),
  ('9628baf0-aa70-56a3-2d87-0a7bcf4a7ca7', 'fd777393-b486-4c79-8b81-67f2a1409bdb', 3, 'multiple_choice', 'Quelles affirmations sur un LAN sont exactes ? (plusieurs réponses)', 'Un LAN est local, géré par une seule organisation, et ses machines se parlent sans Internet : une imprimante partagée en est la preuve. Relier des villes différentes est le rôle d’un WAN.', 'moyen', 7),
  ('eb9ebd2a-5639-af92-8b32-377dc7cf6ee7', 'fd777393-b486-4c79-8b81-67f2a1409bdb', 4, 'single_choice', 'Awa constate que l’imprimante répond et que le ping vers la box réussit, mais que le ping vers 1.1.1.1 échoue. Quelle hypothèse est la plus cohérente ?', 'Les tests réussis prouvent que le LAN fonctionne, commutateur, câbles et carte réseau compris. Seule la sortie vers Internet échoue : on suspecte la box ou la liaison de l’opérateur.', 'difficile', 7),
  ('d57383f2-47ee-5d87-0404-6ca4b8839020', 'e59ab6d0-b7be-cc25-2c4d-ab93c3d3d35d', 1, 'single_choice', 'Quelle unité de données est la bonne à la couche 3 du modèle OSI ?', 'La couche 3, dite réseau, manipule des paquets IP. La trame correspond à la couche 2, le segment à la couche 4 et les bits à la couche 1.', 'facile', 8),
  ('9071a156-2ffd-45a3-b438-d3c2fa69d864', 'e59ab6d0-b7be-cc25-2c4d-ab93c3d3d35d', 2, 'multiple_choice', 'Quelles associations sont correctes ? (plusieurs réponses)', 'Le routeur choisit un chemin IP, ARP relie IP et MAC dans le LAN, et le commutateur transmet des trames selon les adresses MAC. curl teste l’application, pas le support physique.', 'moyen', 8),
  ('6054d030-0888-6b12-ce10-09a203ab261a', 'e59ab6d0-b7be-cc25-2c4d-ab93c3d3d35d', 3, 'single_choice', 'Tu peux joindre la passerelle avec ping et voir son adresse dans ARP, mais curl vers l’intranet renvoie « Connection refused ». Quelle couche dois-tu suspecter d’abord ?', 'Le ping et ARP montrent que les couches basses fonctionnent jusqu’à la passerelle. Le refus de connexion pointe plutôt vers un service qui n’écoute pas, donc transport ou application.', 'difficile', 7),
  ('c5836e1d-9631-897b-ece0-2647034a78ed', 'e59ab6d0-b7be-cc25-2c4d-ab93c3d3d35d', 4, 'true_false', 'Dans le modèle TCP/IP, les couches présentation et session sont généralement regroupées avec l’application.', 'Vrai : TCP/IP simplifie la pile en 4 couches et regroupe les responsabilités hautes dans l’application. Cela ne supprime pas ces fonctions, cela les rassemble.', 'moyen', 7),
  ('a063aa10-2145-dab6-ca79-35041d35ee63', 'cbdd9f3a-380d-19d4-0cdb-e99c6e5f124a', 1, 'single_choice', 'Quel champ change normalement à chaque routeur sur le chemin d’un paquet IPv4 ?', 'Le TTL diminue à chaque passage sur un routeur pour éviter qu’un paquet boucle indéfiniment. L’adresse IP de destination reste la même jusqu’au destinataire, sauf cas particuliers comme le NAT.', 'facile', 8),
  ('82da3103-b196-34f6-8753-657865cd5a2a', 'cbdd9f3a-380d-19d4-0cdb-e99c6e5f124a', 2, 'multiple_choice', 'Que peux-tu affirmer à propos d’une requête HTTP classique transportée sur Ethernet et IPv4 ? (plusieurs réponses)', 'Les MAC appartiennent seulement au saut local et sont réécrites à chaque lien. En revanche, l’adresse IP finale reste stable et TCP ajoute bien les ports source et destination pour la conversation.', 'moyen', 8),
  ('3c5e46d3-a7dc-4b9d-e4b5-d99f4860968c', 'cbdd9f3a-380d-19d4-0cdb-e99c6e5f124a', 3, 'single_choice', 'Dans une capture, tu lis : « IPv4 Src 192.168.1.25, Dst 172.16.5.20, TTL 63 » puis, sur un autre lien, « TTL 62 » pour la même requête. Quelle interprétation est la meilleure ?', 'La baisse de 63 à 62 montre un passage sur un routeur. Les commutateurs ne touchent pas au TTL et rien ici n’indique un changement d’IP ou une fermeture TCP.', 'difficile', 7),
  ('2ab0aa13-447d-6617-d1b2-c720b963b043', 'cbdd9f3a-380d-19d4-0cdb-e99c6e5f124a', 4, 'true_false', 'Une trame Ethernet de 200 octets est au-dessus de la MTU Ethernet classique de 1500 octets.', 'Faux : 200 est bien inférieur à 1500. Une telle trame ne pose donc pas de problème de fragmentation sur un lien Ethernet standard.', 'moyen', 7),
  ('ec35091a-7636-c6e9-68a5-2153f7f51349', '0e2c32fa-917b-b71f-bbf3-4cb4e1ad8fb5', 1, 'single_choice', 'Quel bloc est le plus petit capable de fournir au moins 70 hôtes utilisables ?', 'Un /25 offre 126 hôtes utilisables, ce qui couvre 70 avec de la marge. Un /26 n’en offre que 62, donc il est insuffisant.', 'moyen', 8),
  ('d9b264e0-59d2-181c-fb33-4a2cd1efdf82', '0e2c32fa-917b-b71f-bbf3-4cb4e1ad8fb5', 2, 'multiple_choice', 'Quelles pratiques rendent un plan VLSM plus fiable ? (plusieurs réponses)', 'On place d’abord les gros blocs, on contrôle qu’ils ne se recouvrent pas et on prévoit un peu de croissance. Une passerelle au hasard complique la documentation et favorise les erreurs.', 'moyen', 8),
  ('a1401c47-fea1-5530-b97e-b1a7db18973e', '0e2c32fa-917b-b71f-bbf3-4cb4e1ad8fb5', 3, 'single_choice', 'Dans le plan ci-dessous, quelle passerelle correspond au sous-réseau 10.2.0.160/28 si l’équipe utilise toujours la première adresse utilisable ?
