  ('3006f7d5-54ad-857e-c29a-a6a4410a6cd6', 'ed9e0a76-17c0-1877-7ec6-08c66d3ff713', 1, '« Panne réseau réglée »', false),
  ('33be17fb-930a-2f5e-0dab-6fe8e5a0dae3', 'ed9e0a76-17c0-1877-7ec6-08c66d3ff713', 2, '« Internet KO, voir Nadia »', false),
  ('b13f85fe-d234-5fba-406d-508cdb0ce263', 'ed9e0a76-17c0-1877-7ec6-08c66d3ff713', 3, '« VLAN 130 absent du trunk Fa0/24, corrigé puis vérifié par « show interfaces trunk » et un test invité »', true),
  ('a2d9cbed-6e11-53da-34f1-5c3fe0d5080a', 'ed9e0a76-17c0-1877-7ec6-08c66d3ff713', 4, '« Il fallait redémarrer »', false)
insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('fcfd320e-7845-1004-88d5-78961077a035', 'tp-reseau-domestique', 'TP 1 : construire le réseau d’une maison', 'Relie un PC, un portable et une imprimante à Internet : DHCP, IPv6 par autoconfiguration et partage d’une adresse publique. Prouve que tu sais lire un ipconfig /all.', 'reseau', 'debutant', 140, array['Calculer l’adresse de diffusion et la taille d’une plage DHCP', 'Lire une sortie ipconfig /all : adresse, bail, passerelle, DNS, IPv6', 'Découper une délégation IPv6 en sous-réseaux /64', 'Expliquer la traduction d’adresse avec ports (PAT)']::text[], array['Les extrémités d’une plage comptent toutes les deux.', 'La sortie fournie se lit ligne par ligne : cherche « Bail obtenu » et « Bail expirant ».', 'Un /56 contient 2 puissance (64 moins 56) sous-réseaux /64.']::text[], '{}'::text[], 300, 'c9468857-0122-856c-b60f-5c05e13778a7', 'packet_tracer', 'Une famille veut relier un PC, un portable et une imprimante à Internet. Le réseau local est 192.168.50.0/24, le routeur R-Maison en est la passerelle et attribue des adresses par DHCP entre 192.168.50.100 et 192.168.50.150. Le fournisseur d’accès délègue le préfixe IPv6 2001:db8:5a00::/56. Ta mission : construire la topologie (dans Packet Tracer si tu l’as, sinon sur le papier), compléter le service DHCP, lire la sortie ipconfig /all relevée sur PC-Salon et répondre aux questions de dimensionnement.', array['Travaille uniquement sur la topologie et les fichiers fournis : ne configure aucun équipement réel qui ne t’appartient pas.', 'Packet Tracer est facultatif : les tâches se valident ici, avec ou sans le logiciel.']::text[], array['Cisco Packet Tracer (gratuit, sur ton ordinateur, facultatif)', 'Visionneuse de journaux CyberPingo', 'Une calculatrice ou Node.js pour vérifier les calculs']::text[], true, false, 45),
  ('bffff6ca-ef0c-371d-d473-89ee42d3eb20', 'tp-vlan-pme', 'TP 2 : VLAN, trunk et routage inter-VLAN pour la PME Kora', 'Sépare trois services sur un seul commutateur, relie-les par un trunk à un routeur et protège le réseau d’administration. Prouve que tu sais lire un show vlan brief.', 'reseau', 'intermediaire', 180, array['Lire un show vlan brief et un show interfaces trunk', 'Configurer une sous-interface 802.1Q de routeur', 'Écrire une ACL étendue qui isole un VLAN', 'Rapprocher le plan documenté de la configuration observée']::text[], array['Le routeur sur un bras a une sous-interface par VLAN, avec le numéro du VLAN dans son nom et dans la commande d’encapsulation.', 'Le masque inverse d’un /24 s’écrit 0.0.0.255.', 'Une ACL placée au plus près de la source évite de faire voyager des paquets qui seront refusés.']::text[], '{}'::text[], 310, 'c9468857-0122-856c-b60f-5c05e13778a7', 'packet_tracer', 'Kora loue des locaux et veut séparer trois services sur un seul commutateur : l’administration (VLAN 10), les employés et les invités (VLAN 30). Un VLAN de gestion sert à administrer les équipements. Un routeur R1 relie les VLAN par un seul trunk, et les invités ne doivent pas atteindre l’administration. Ta mission : appliquer la démarche du guide aux autres VLAN, lire les sorties fournies de SW1 et écrire les commandes demandées.', array['Travaille uniquement sur la topologie et les fichiers fournis : ne configure aucun équipement réel qui ne t’appartient pas.', 'Écris les commandes exactement comme dans Cisco IOS : l’abréviation habituelle des interfaces est acceptée.']::text[], array['Cisco Packet Tracer (gratuit, sur ton ordinateur, facultatif)', 'Visionneuse de journaux CyberPingo', 'Le guide du TP 2']::text[], true, false, 70),
  ('b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 'tp-multi-sites', 'TP 3 : relier trois sites avec des routes statiques', 'Relie le siège de Kora à deux agences par des liaisons /30, écris les routes statiques nécessaires et repère la route qui manque dans une table de routage.', 'reseau', 'intermediaire', 160, array['Dimensionner une liaison point à point en /30', 'Écrire des routes statiques et une route par défaut', 'Lire une table de routage et y repérer une route manquante', 'Résumer deux réseaux voisins en une seule route']::text[], array['Un prochain saut est l’adresse du routeur voisin sur la liaison commune.', 'Les agences n’ont qu’une sortie : le siège.', 'Deux /24 voisins se résument en un /23.']::text[], '{}'::text[], 320, 'c9468857-0122-856c-b60f-5c05e13778a7', 'packet_tracer', 'Kora ouvre deux agences. Le siège (10.60.0.0/24) est relié à l’agence Nord (10.60.4.0/24) par la liaison 172.20.0.0/30, et à l’agence Sud (10.60.5.0/24) par la liaison 172.20.0.4/30. Les agences ne sont reliées qu’au siège. Ta mission : écrire les routes statiques qui permettent aux trois sites de communiquer, puis lire la table de routage de R-Siege, relevée sur un réseau dont un test échoue, pour trouver ce qui manque.', array['Travaille uniquement sur la topologie et les fichiers fournis : ne configure aucun équipement réel qui ne t’appartient pas.', 'Écris les commandes comme dans Cisco IOS : adresse de réseau, masque en notation décimale, puis prochain saut.']::text[], array['Cisco Packet Tracer (gratuit, sur ton ordinateur, facultatif)', 'Visionneuse de journaux CyberPingo', 'Une calculatrice de sous-réseaux']::text[], true, false, 60),
  ('f608e920-de51-f74c-f1c8-0af0a9bff9e3', 'incident-reseau-kora', 'TP 4 : incident réseau chez Kora', 'Les comptables n’atteignent plus leur serveur, le Wi-Fi invités est coupé et un poste ne reçoit plus d’adresse. Trouve les quatre pannes cachées dans les relevés d’un poste, d’un routeur et d’un commutateur.', 'reseau', 'intermediaire', 320, array['Suivre le chemin d’un paquet pour localiser une panne', 'Rapprocher une adresse MAC, un port et un VLAN', 'Lire un trunk, une ACL et leurs compteurs', 'Repérer un décalage d’horloge entre équipements']::text[], array['Teste de l’intérieur vers l’extérieur : poste, passerelle, serveur.', 'Retrouve l’adresse physique du poste isolé, puis cherche-la dans la table MAC.', 'Compare la liste des VLAN du commutateur avec celle du trunk.']::text[], '{}'::text[], 330, 'c9468857-0122-856c-b60f-5c05e13778a7', 'logs', 'Un ticket signale que les postes de la comptabilité n’atteignent plus le serveur de fichiers FS01, que le Wi-Fi des invités est coupé et qu’un poste de l’atelier n’obtient plus d’adresse. Le fichier fourni rassemble les relevés faits sur trois postes, le routeur R1 et le commutateur SW1. Plusieurs défauts se cumulent : corriger le premier en révèle un autre. Ta mission : les trouver un à un en suivant le chemin des paquets, nommer la couche concernée, écrire la correction et expliquer pourquoi les horloges des équipements ne concordent pas. Ce laboratoire valide les compétences sur les modèles en couches, les VLAN et le trunk, le filtrage par ACL et le diagnostic : sans indice, il demande de recouper plusieurs sources.', array['Évaluation : réponds sans aide extérieure, comme en situation réelle.', 'Appuie chaque réponse sur les relevés fournis, pas sur une supposition.', 'Les corrections s’écrivent en commandes Cisco IOS exactes.']::text[], array['Visionneuse de journaux CyberPingo', 'Cisco Packet Tracer (facultatif, pour reproduire les pannes)', 'Un tableur ou du papier pour noter ta chronologie']::text[], false, true, 60),
  ('1592d04b-debc-33f8-aa67-bd5d34a00280', 'projet-reseau-kora', 'Projet final : concevoir et documenter le réseau de Kora', 'Découpe 10.80.0.0/22 pour cinq services avec VLSM, prépare le plan IPv6, dimensionne le DHCP et la traduction d’adresse, puis repère les incohérences d’un inventaire existant.', 'reseau', 'avance', 380, array['Dimensionner des sous-réseaux avec VLSM', 'Construire un plan IPv6 à partir d’un /48', 'Dimensionner une plage DHCP et justifier la traduction PAT', 'Relire une documentation et y repérer des incohérences']::text[], array['Pour chaque besoin, cherche la plus petite puissance de 2 qui couvre les adresses utilisables nécessaires.', 'Le quatrième groupe IPv6 reprend le numéro du VLAN en hexadécimal.', 'Dans l’inventaire, vérifie chaque adresse contre le réseau de son VLAN.']::text[], '{}'::text[], 340, 'c9468857-0122-856c-b60f-5c05e13778a7', 'packet_tracer', 'Kora regroupe ses équipes dans un nouveau bâtiment et te confie son réseau. Le cahier des charges fourni donne le bloc IPv4 10.80.0.0/22, le préfixe IPv6 2001:db8:4b00::/48, le lien vers l’opérateur, les besoins de cinq services, les services à prévoir et les règles de filtrage. Ta mission : calculer le plan d’adressage (du plus grand besoin au plus petit, sans trou), déduire le plan IPv6, dimensionner le DHCP, écrire la route vers l’opérateur et prévoir la table de routage du routeur, puis relire l’inventaire existant pour y repérer les incohérences. La maquette dans Packet Tracer est facultative ; le modèle de documentation fourni te sert à rédiger ton dossier, que tu peux déposer pour une relecture. Ce laboratoire valide les compétences d’adressage VLSM et IPv6, de DHCP et de traduction d’adresse, de routage statique et de documentation.', array['Évaluation : réponds sans aide extérieure, comme en situation réelle.', 'Respecte la règle d’allocation du cahier des charges : du plus grand besoin au plus petit, sans trou.', 'N’inscris aucun mot de passe dans ta documentation.']::text[], array['Cisco Packet Tracer (gratuit, facultatif)', 'Une calculatrice de sous-réseaux ou Node.js pour vérifier les calculs', 'Un éditeur de texte pour le modèle de documentation']::text[], true, true, 90)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('7b8d48bd-a525-a3c2-1777-2228c69691ba', 'fcfd320e-7845-1004-88d5-78961077a035', 1, 'Quelle est l’adresse de diffusion du réseau 192.168.50.0/24 ?', 'C’est la dernière adresse du bloc : tous les bits de la partie hôte valent 1.', 'Adresse IPv4'),
  ('8700be9c-8de0-07b2-9d6a-076780ebe09b', 'fcfd320e-7845-1004-88d5-78961077a035', 2, 'Combien d’adresses la plage DHCP de 192.168.50.100 à 192.168.50.150 contient-elle, extrémités comprises ?', 'Soustrais les deux derniers octets, puis ajoute un : les deux extrémités comptent.', 'Un nombre entier'),
  ('964ad3e6-e68c-af57-069e-ec026c840c4c', 'fcfd320e-7845-1004-88d5-78961077a035', 3, 'L’imprimante a l’adresse fixe 192.168.50.20. Cette adresse fait-elle partie de la plage DHCP ? (oui ou non)', 'Compare ce dernier octet avec ceux de la plage.', 'oui ou non'),
  ('16e2378a-8c8b-ad6b-1692-5ae27b33c0f6', 'fcfd320e-7845-1004-88d5-78961077a035', 4, 'Dans la sortie ipconfig /all fournie, quelle adresse IPv4 PC-Salon a-t-il obtenue ?', 'Cherche la ligne « Adresse IPv4 ».', 'Adresse IPv4'),
  ('b41c260b-d9d3-457c-31dd-1f4f19f1ed39', 'fcfd320e-7845-1004-88d5-78961077a035', 5, 'Quelle est la durée du bail DHCP de PC-Salon, en heures ?', 'Compare « Bail obtenu » et « Bail expirant ».', 'Un nombre d’heures'),
  ('5a7ec38b-4c81-f310-aafa-2495df9c51fb', 'fcfd320e-7845-1004-88d5-78961077a035', 6, 'Quelle adresse est annoncée comme serveur DNS ?', 'Cherche la ligne « Serveurs DNS ».', 'Adresse IPv4'),
  ('e6e7299e-18de-532e-24ae-0a5138ea44f0', 'fcfd320e-7845-1004-88d5-78961077a035', 7, 'Quel préfixe /64 retrouve-t-on au début de l’adresse IPv6 globale de PC-Salon ? (notation compressée, avec /64)', 'Garde les quatre premiers groupes de l’adresse IPv6 sans les « fe80 ».', 'Préfixe, par exemple 2001:db8:1::/64'),
  ('27846dec-d1ea-d59c-7dca-9a2be63a38bc', 'fcfd320e-7845-1004-88d5-78961077a035', 8, 'Le fournisseur délègue 2001:db8:5a00::/56. Combien de sous-réseaux /64 cette délégation contient-elle ?', 'Il y a 64 moins 56 bits de plus pour numéroter les sous-réseaux.', 'Un nombre entier'),
  ('8f5103bc-582e-0ed4-3140-151e43990978', 'fcfd320e-7845-1004-88d5-78961077a035', 9, 'Écris en notation compressée l’adresse 2001:0db8:5a00:0001:0000:0000:0000:0001.', 'Retire les zéros de tête de chaque groupe, puis remplace la plus longue suite de groupes nuls par « :: ».', 'Adresse IPv6 compressée'),
  ('6c6a93b7-8436-f682-5356-afe1c87744bd', 'fcfd320e-7845-1004-88d5-78961077a035', 10, 'Quelle commande Windows affiche l’adresse MAC, le bail DHCP, la passerelle et les serveurs DNS ?', 'C’est ipconfig avec une option qui veut dire « tout ».', 'Commande Windows'),
  ('0f8de72d-39de-ba26-8192-d29a56972c08', 'fcfd320e-7845-1004-88d5-78961077a035', 11, 'Le foyer n’a qu’une adresse publique, celle de la sortie de R-Maison. Combien d’adresses publiques faut-il au minimum pour que tous ses appareils aillent sur Internet avec la traduction PAT ?', 'PAT distingue les conversations par leur numéro de port.', 'Un nombre entier'),
  ('41c7bfd5-0004-9d29-0449-5a8fa2898700', 'fcfd320e-7845-1004-88d5-78961077a035', 12, 'Dans la commande « ip nat inside source list 1 interface GigabitEthernet0/1 … », quel mot-clé final active la traduction avec ports (PAT) ?', 'Il signifie « surcharge » en anglais.', 'Un mot-clé IOS'),
  ('2033edea-64db-a636-258f-b0725449b1df', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 1, 'Quel est l’identifiant du VLAN réservé aux invités ?', 'Relis le briefing.', 'Un numéro de VLAN'),
  ('c0605e80-e012-c26e-6f0a-043fc826d62f', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 2, 'D’après show vlan brief, combien de ports d’accès le VLAN 20 compte-t-il ?', 'Compte les ports listés sur les lignes du VLAN 20 (la liste peut continuer à la ligne suivante).', 'Un nombre entier'),
  ('ace03b3d-22f9-7475-e110-82a0b5c9e0ba', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 3, 'Quel est le seul port de SW1 en mode trunk ? (nom court, par exemple Fa0/1)', 'Les ports en trunk n’apparaissent pas dans show vlan brief : regarde show interfaces trunk.', 'Nom d’interface'),
  ('764b01d6-6b04-78e1-2cbb-ffce08a81a54', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 4, 'Quels VLAN la sortie de show interfaces trunk autorise-t-elle sur le trunk ? (numéros séparés par des virgules)', 'Regarde le bloc « Vlans allowed on trunk ».', 'Par exemple 10,20'),
  ('b99d6955-d42b-44c5-0026-58dd2deddb70', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 5, 'Quel est le VLAN natif du trunk ?', 'Dernière colonne de la première table de show interfaces trunk.', 'Un numéro de VLAN'),
  ('5c58b7cd-e62d-2cd4-1968-fbf15e6a3695', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 6, 'Quelle commande, dans la sous-interface Gi0/0.30 de R1, associe cette sous-interface au VLAN 30 avec l’étiquette 802.1Q ?', 'Adapte la commande « encapsulation » de l’exemple du guide.', 'Commande IOS'),
  ('9c127683-bdbb-059a-9633-6d6461f0ae22', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 7, 'Quelle adresse donnes-tu à la sous-interface du VLAN 20 de R1, qui sert de passerelle aux employés ?', 'La passerelle est la première adresse utilisable du réseau du VLAN.', 'Adresse IPv4'),
  ('1a9c5284-c098-bc05-690d-2115605b65d7', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 8, 'Combien de VLAN l’administrateur a-t-il créés, sans compter le VLAN 1 par défaut ni les VLAN 1002 à 1005 réservés ?', 'Compte les VLAN nommés dans show vlan brief.', 'Un nombre entier'),
  ('20549903-29fa-06e1-31ec-80d068dca636', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 9, 'Écris la ligne d’ACL étendue numérotée 110 qui refuse tout le trafic IP des invités (10.40.30.0/24) vers l’administration (10.40.10.0/24).', 'Format : access-list <numéro> deny ip <réseau source> <masque inverse> <réseau destination> <masque inverse>.', 'Commande IOS en une ligne'),
  ('98606d62-2115-49c9-8985-4ce7899bb8c5', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 10, 'Sur quelle interface et dans quel sens appliques-tu cette ACL pour bloquer le trafic au plus près de sa source ? (par exemple Gi0/0.10 out)', 'La source est le VLAN des invités, et le trafic entre dans le routeur par sa sous-interface.', 'Interface et sens'),
  ('6c9b5a8f-96dc-3eb8-1799-1acf610e892c', 'bffff6ca-ef0c-371d-d473-89ee42d3eb20', 11, 'Quel VLAN créé n’a aucun port d’accès dans show vlan brief, parce qu’il ne sert qu’à administrer les équipements ?', 'Cherche la ligne sans port.', 'Un numéro de VLAN'),
  ('c3d0ee7c-0986-bcb8-1fe1-309b2d1cc237', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 1, 'Combien d’adresses utilisables contient un réseau /30 comme celui d’une liaison entre deux routeurs ?', 'Un /30 contient 4 adresses, dont deux sont réservées.', 'Un nombre entier'),
  ('3f6a120e-5ac5-cd11-82d2-f9d475ead8c8', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 2, 'Quelle est l’adresse de diffusion de la liaison 172.20.0.4/30 ?', 'C’est la dernière adresse du bloc de 4 adresses.', 'Adresse IPv4'),
  ('adfee18e-a9df-2e4e-a41a-b314c8bdf8ce', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 3, 'Écris la commande à saisir sur R-Nord pour joindre le réseau local de l’agence Sud.', 'Format : ip route <réseau> <masque> <prochain saut>. Le prochain saut de R-Nord est le siège, sur la liaison Nord.', 'Commande IOS'),
  ('7b489190-3b44-ffb1-d490-03a5ef759c33', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 4, 'Écris la commande qui définit la route par défaut de R-Sud, dont la seule sortie est le siège.', 'La route par défaut s’écrit avec le réseau 0.0.0.0 et le masque 0.0.0.0.', 'Commande IOS'),
  ('4cec5d26-3d1a-30a5-9273-3120cd944b0a', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 5, 'Dans la table de routage de R-Siege fournie, quel réseau est absent ? (réseau et préfixe, par exemple 10.0.0.0/24)', 'Compare les routes S de la table avec les réseaux locaux des agences.', 'Réseau avec préfixe'),
  ('5583233a-4c87-ab8d-78da-733c2e2ac159', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 6, 'Écris la commande qui ajoute à R-Siege la route manquante.', 'Le prochain saut est l’adresse de R-Sud sur la liaison Sud.', 'Commande IOS'),
  ('3f87868f-b71e-1a2d-0550-69d353bfe8d8', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 7, 'Quel préfixe unique résume les réseaux locaux des agences Nord et Sud ?', 'Deux /24 voisins se regroupent dans un /23.', 'Réseau avec préfixe'),
  ('5c25e314-20ca-7064-d19a-09f50cfaadd3', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 8, 'Quelle lettre désigne une route statique dans la colonne de gauche de show ip route ?', 'Regarde la légende « Codes » en haut de la sortie.', 'Une lettre'),
  ('23a97b41-0e0d-2383-b152-36720f3de75e', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 9, 'Quelle est la distance administrative d’une route statique, d’après le [1/0] de la route de R-Siege ?', 'Le premier nombre entre crochets est la distance administrative.', 'Un nombre entier'),
  ('157220bf-4340-9599-8a02-da7c474888a7', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 10, 'R-Nord a une route par défaut vers le siège. A-t-il besoin d’une route spécifique vers le réseau de l’agence Sud pour la joindre ? (oui ou non)', 'Que fait un routeur d’un paquet dont la destination ne figure pas dans sa table ?', 'oui ou non'),
  ('784bec19-1d98-0d3e-04e4-31ac5e0218ec', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 1, 'Quelle passerelle par défaut est configurée sur PC-Compta ?', 'Relis le ipconfig de la section 1.', 'Adresse IPv4'),
  ('b06d83d7-804b-dbee-c5e2-188f38cd60e0', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 2, 'Quelle est la cause du premier échec (le ping vers le serveur depuis PC-Compta) ? Réponds par un seul mot : passerelle, vlan, trunk ou acl.', 'Le ping vers 10.40.20.1 réussit : le poste joint son routeur. Que se passe-t-il pour tout ce qui est hors du réseau local ?', 'Un mot'),
  ('690a4071-ce8c-4d8b-c6ee-83be8bc6d761', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 3, 'À quelle couche du modèle OSI se situe cette panne de passerelle ? (donne le numéro)', 'La passerelle est une adresse IP, utilisée pour router.', 'Un numéro de couche'),
  ('4e3894fc-de10-0900-e1fb-55dc78b2c73a', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 4, 'Sur quel port de SW1 est branché PC-Atelier ? (cherche son adresse physique 00-90-2B-7A-31-D5 dans la table MAC ; nom court, par exemple Fa0/3)', 'Les adresses MAC s’écrivent par groupes de quatre chiffres dans la table de SW1.', 'Nom d’interface'),
  ('e5968c5d-c0c4-a584-7a55-187e9ba88efe', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 5, 'Dans quel VLAN ce port est-il affecté, alors qu’il devrait appartenir au VLAN des employés ?', 'La ligne de la table MAC donne le VLAN dans lequel l’adresse a été apprise.', 'Un numéro de VLAN'),
  ('73af7247-41d7-171a-11a2-6329344999f0', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 6, 'Quelle commande, saisie sur le port Fa0/12, remet ce poste dans le VLAN des employés (VLAN 20) ?', 'C’est la commande qui affecte un port d’accès à un VLAN.', 'Commande IOS'),
  ('7eb6c68d-736f-7491-d385-1fbe5b755708', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 7, 'Quel VLAN manque dans la liste des VLAN autorisés sur le trunk et explique la panne du Wi-Fi des invités ?', 'Compare la liste du trunk avec les VLAN de show vlan brief.', 'Un numéro de VLAN'),
  ('09ca62e8-0b5f-630e-34b1-a83b93dc9e86', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 8, 'Quelle commande, sur l’interface trunk, ajoute ce VLAN à la liste sans retirer les autres ?', 'Le mot-clé « add » complète la liste au lieu de la remplacer.', 'Commande IOS'),
  ('d31d383c-de6d-86a1-9e07-25ff9eac5c2c', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 9, 'Après correction de la passerelle, le ping vers FS01 échoue encore. Quelle ligne d’ACL en est la cause ? (copie la règle, sans le compteur entre parenthèses)', 'Regarde les compteurs « matches » de show access-lists.', 'Ligne d’ACL'),
  ('401ed52d-ee46-b9df-3b1e-cd856a60be64', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 10, 'Combien de paquets cette règle a-t-elle déjà refusés ?', 'Le compteur est à la fin de la ligne.', 'Un nombre entier'),
  ('bdde2d0c-a757-efd2-1a33-5885714647fa', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 11, 'Quelle commande, en mode de configuration de l’ACL SERVEURS, supprime cette ligne fautive ?', 'En mode ACL nommée, on supprime une ligne grâce à son numéro de séquence.', 'Commande IOS'),
  ('0cdc681b-6e9f-d4d6-91e7-aacb793fdff8', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 12, 'Les deux extrémités du même lien (Gi0/0 de R1 et Gi0/1 de SW1) ont changé d’état au même moment. Quel décalage d’horloge, en minutes, sépare les deux journaux ?', 'Compare les heures des deux événements « changed state to down ».', 'Un nombre de minutes'),
  ('ce36dcdd-4cbd-b02d-adb2-03b4d7300450', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 13, 'Quel protocole synchronise les horloges des équipements sur une source de temps commune ?', 'Son nom veut dire « protocole de temps réseau ».', 'Un sigle'),
  ('e212805f-5aac-43d7-dea7-0a410de7df80', '1592d04b-debc-33f8-aa67-bd5d34a00280', 1, 'Quel est le plus petit préfixe qui peut accueillir les 110 adresses utilisables du service Employés ? (par exemple /24)', 'Un préfixe /n offre 2 puissance (32 moins n) adresses, moins deux.', 'Préfixe, par exemple /24'),
  ('863a908d-c006-b30d-889b-105b698ae8d8', '1592d04b-debc-33f8-aa67-bd5d34a00280', 2, 'Quelle est l’adresse réseau du sous-réseau Administration, alloué juste après Employés ?', 'Le sous-réseau Employés occupe le début du bloc ; Administration commence juste après.', 'Adresse IPv4'),
  ('ca61eb9b-292c-dc02-c7c4-a9d5e03c3a79', '1592d04b-debc-33f8-aa67-bd5d34a00280', 3, 'Quelle est l’adresse de diffusion du sous-réseau Invités ?', 'Invités a besoin de 28 adresses, donc d’un /27, et suit Administration.', 'Adresse IPv4'),
  ('9b96f7bb-d210-3966-fc44-1790e0b252e3', '1592d04b-debc-33f8-aa67-bd5d34a00280', 4, 'Quelle est la première adresse utilisable du sous-réseau Serveurs ? (c’est aussi sa passerelle)', 'Serveurs (12 adresses, un /28) suit Invités.', 'Adresse IPv4'),
  ('237ed1f1-36b9-f124-71f6-55bdff2af82a', '1592d04b-debc-33f8-aa67-bd5d34a00280', 5, 'Quel masque (notation décimale) porte le sous-réseau Gestion, qui doit accueillir 5 adresses utilisables ?', 'Trois bits d’hôte offrent 8 adresses, donc 6 utilisables.', 'Masque décimal'),
  ('3b67ad37-6b05-3366-48b2-ce5fc4d440f4', '1592d04b-debc-33f8-aa67-bd5d34a00280', 6, 'Quelle est la première adresse libre du bloc 10.80.0.0/22 une fois les cinq sous-réseaux alloués ?', 'Elle suit directement le dernier sous-réseau alloué (Gestion).', 'Adresse IPv4'),
  ('f3be1e9d-6a10-0c0e-9235-4ffb4372c866', '1592d04b-debc-33f8-aa67-bd5d34a00280', 7, 'Combien de sous-réseaux /27 le bloc 10.80.0.0/22 contient-il en tout ?', 'Divise le nombre d’adresses du bloc par celui d’un /27.', 'Un nombre entier'),
  ('91e791b8-584f-3b13-6011-4e369067e013', '1592d04b-debc-33f8-aa67-bd5d34a00280', 8, 'Combien de sous-réseaux /64 le préfixe 2001:db8:4b00::/48 peut-il contenir ?', 'Il y a 64 moins 48 bits pour numéroter les sous-réseaux.', 'Un nombre entier'),
  ('097cdb2f-455b-3dd0-2c75-4c48bd43c790', '1592d04b-debc-33f8-aa67-bd5d34a00280', 9, 'Quel est le /64 du VLAN des invités (VLAN 30), sachant que le quatrième groupe reprend le numéro du VLAN en hexadécimal ? (notation compressée, avec /64)', '30 en hexadécimal s’écrit 1e.', 'Préfixe, par exemple 2001:db8:1::/64'),
  ('94ceef75-9643-14ab-d729-6c4be4dd9965', '1592d04b-debc-33f8-aa67-bd5d34a00280', 10, 'Quelle est la première adresse de la plage DHCP des employés, sachant que les dix premières adresses utilisables sont exclues ?', 'La passerelle est la première adresse utilisable ; les dix premières sont exclues.', 'Adresse IPv4'),
  ('94f88e65-38cd-efbc-0b69-fd4894cb3799', '1592d04b-debc-33f8-aa67-bd5d34a00280', 11, 'Combien d’adresses la plage DHCP des employés contient-elle, de sa première adresse à la dernière adresse utilisable du sous-réseau ?', 'Dernière utilisable moins première de la plage, plus un.', 'Un nombre entier'),
  ('2405630b-e46d-4558-43dd-7425e03daa13', '1592d04b-debc-33f8-aa67-bd5d34a00280', 12, 'Kora n’a qu’une adresse publique. Combien d’adresses publiques faut-il au minimum pour faire sortir tous les VLAN avec PAT ?', 'PAT distingue les conversations par leur numéro de port.', 'Un nombre entier'),
  ('292cb78a-64fb-6c19-55b9-b64189a47da5', '1592d04b-debc-33f8-aa67-bd5d34a00280', 13, 'Écris la commande qui définit la route par défaut du routeur de Kora vers l’opérateur, dont l’adresse sur le lien 192.0.2.0/30 figure dans le cahier des charges.', 'La route par défaut utilise le réseau 0.0.0.0 et le masque 0.0.0.0 ; le prochain saut est l’adresse de l’opérateur.', 'Commande IOS'),
  ('61b0a2ee-8420-5bb5-ab2b-eeae498731f3', '1592d04b-debc-33f8-aa67-bd5d34a00280', 14, 'Combien de routes connectées (code C dans show ip route) le routeur de Kora contiendra-t-il, une fois les cinq sous-réseaux des VLAN et le lien vers l’opérateur configurés ?', 'Chaque interface active porte un réseau connecté ; les routes locales (code L) ne sont pas des routes C.', 'Un nombre entier'),
  ('8ccd570c-840a-749f-52f9-bc7fdadd1489', '1592d04b-debc-33f8-aa67-bd5d34a00280', 15, 'Dans l’inventaire à vérifier, quelle adresse IP est attribuée à deux équipements différents ?', 'Cherche les doublons dans la colonne des adresses.', 'Adresse IPv4'),
  ('f93c4f3f-e4ed-3080-4b2f-091f85ba2282', '1592d04b-debc-33f8-aa67-bd5d34a00280', 16, 'Quel équipement de l’inventaire a une adresse qui ne se trouve pas dans le sous-réseau de son VLAN ?', 'Compare l’adresse de chaque équipement avec le réseau de son VLAN dans le plan en vigueur.', 'Nom de l’équipement'),
  ('410e4670-46cd-d536-6bcf-74fe972faf08', '1592d04b-debc-33f8-aa67-bd5d34a00280', 17, 'Quel équipement de l’inventaire n’a aucune passerelle indiquée ?', 'Cherche la case vide de la dernière colonne.', 'Nom de l’équipement')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('7b8d48bd-a525-a3c2-1777-2228c69691ba', array['192.168.50.255']::text[], 'Le réseau 192.168.50.0/24 se termine par 192.168.50.255. Cette dernière adresse est la diffusion : on ne peut l’attribuer à aucun appareil.'),
  ('8700be9c-8de0-07b2-9d6a-076780ebe09b', array['51']::text[], 'De 192.168.50.100 à 192.168.50.150, la plage compte 51 adresses (150 moins 100, plus 1).'),
  ('964ad3e6-e68c-af57-069e-ec026c840c4c', array['non', 'no']::text[], '192.168.50.20 est en dehors de la plage 192.168.50.100 à 192.168.50.150 : le service DHCP ne la distribuera jamais, ce qui évite un conflit d’adresse avec l’imprimante.'),
  ('16e2378a-8c8b-ad6b-1692-5ae27b33c0f6', array['192.168.50.100']::text[], 'PC-Salon a reçu 192.168.50.100, la première adresse de la plage : c’est la première machine qui a demandé un bail.'),
  ('b41c260b-d9d3-457c-31dd-1f4f19f1ed39', array['24', '24 heures', '24h']::text[], 'Le bail est obtenu un jour et expire le lendemain à la même heure : 24 heures, la durée par défaut du service DHCP d’un routeur Cisco.'),
  ('5a7ec38b-4c81-f310-aafa-2495df9c51fb', array['192.168.50.1']::text[], 'Le routeur 192.168.50.1 joue aussi le rôle de relais DNS : le service DHCP annonce son adresse avec l’option « dns-server ».'),
  ('e6e7299e-18de-532e-24ae-0a5138ea44f0', array['2001:db8:5a00:1::/64', '2001:db8:5a00:1::']::text[], 'Le PC combine le préfixe 2001:db8:5a00:1::/64 annoncé par le routeur et un identifiant d’interface dérivé de son adresse MAC : c’est l’autoconfiguration SLAAC.'),
  ('27846dec-d1ea-d59c-7dca-9a2be63a38bc', array['256']::text[], 'Entre /56 et /64, il y a 8 bits pour numéroter les sous-réseaux : 2 puissance 8, soit 256 sous-réseaux /64.'),
  ('8f5103bc-582e-0ed4-3140-151e43990978', array['2001:db8:5a00:1::1']::text[], 'Les zéros de tête disparaissent (0db8 devient db8, 0001 devient 1) et les trois groupes nuls consécutifs deviennent « :: » : 2001:db8:5a00:1::1.'),
  ('6c6a93b7-8436-f682-5356-afe1c87744bd', array['ipconfig /all', 'ipconfig.exe /all']::text[], 'ipconfig seul n’affiche que l’adresse, le masque et la passerelle. L’option /all ajoute l’adresse physique, le bail DHCP et les serveurs DNS : c’est la commande de référence pour documenter un poste.'),
  ('0f8de72d-39de-ba26-8192-d29a56972c08', array['1', 'une', 'un', '1 adresse']::text[], 'Avec PAT, le routeur remplace l’adresse source par son adresse publique et distingue chaque conversation par un numéro de port : une seule adresse publique suffit pour de nombreux appareils.'),
  ('41c7bfd5-0004-9d29-0449-5a8fa2898700', array['overload']::text[], 'Le mot-clé overload autorise plusieurs adresses internes à partager l’adresse de l’interface de sortie en se distinguant par leur port. Sans lui, une seule adresse interne peut être traduite à la fois.'),
  ('2033edea-64db-a636-258f-b0725449b1df', array['30']::text[], 'Les invités sont dans le VLAN 30, réseau 10.40.30.0/24. Séparer les invités dans un VLAN dédié permet ensuite de leur appliquer des règles de filtrage propres.'),
  ('c0605e80-e012-c26e-6f0a-043fc826d62f', array['8']::text[], 'Le VLAN 20 compte 8 ports, de Fa0/9 à Fa0/16. La liste de ports continue sur la ligne suivante quand elle est trop longue.'),
  ('ace03b3d-22f9-7475-e110-82a0b5c9e0ba', array['gi0/1', 'g0/1', 'gigabitethernet0/1', 'gigabitethernet 0/1', 'gig0/1']::text[], 'Gi0/1 est le lien trunk vers R1. Un port en trunk transporte plusieurs VLAN : il n’appartient à aucun d’eux et n’apparaît donc pas dans show vlan brief.'),
  ('764b01d6-6b04-78e1-2cbb-ffce08a81a54', array['10,20,30,99', '10, 20, 30, 99', '10 20 30 99', '10;20;30;99']::text[], 'Le trunk transporte les VLAN 10,20,30,99. Un VLAN absent de cette liste n’est jamais transmis à l’autre extrémité : c’est une cause classique de panne ciblée.'),
  ('b99d6955-d42b-44c5-0026-58dd2deddb70', array['99']::text[], 'Le VLAN natif est le 99, le VLAN de gestion. Ses trames circulent sans étiquette 802.1Q : les deux extrémités du trunk doivent s’accorder sur ce numéro.'),
  ('5c58b7cd-e62d-2cd4-1968-fbf15e6a3695', array['encapsulation dot1q 30']::text[], '« encapsulation dot1q 30 » indique à la sous-interface de traiter les trames étiquetées 30. Sans cette commande, le routeur ne saurait pas quelle sous-interface doit recevoir ces trames.'),
  ('9c127683-bdbb-059a-9633-6d6461f0ae22', array['10.40.20.1']::text[], 'Le réseau du VLAN 20 est 10.40.20.0/24. Sa première adresse utilisable, 10.40.20.1, devient la passerelle des postes du VLAN.'),
  ('1a9c5284-c098-bc05-690d-2115605b65d7', array['4']::text[], 'Quatre VLAN ont été créés : 10 (Administration), 20 (Employes), 30 (Invites), 99 (Gestion). Les VLAN 1 et 1002 à 1005 existent d’origine.'),
  ('20549903-29fa-06e1-31ec-80d068dca636', array['access-list 110 deny ip 10.40.30.0 0.0.0.255 10.40.10.0 0.0.0.255', '110 deny ip 10.40.30.0 0.0.0.255 10.40.10.0 0.0.0.255']::text[], 'Le masque inverse d’un /24 est 0.0.0.255. La ligne « access-list 110 deny ip 10.40.30.0 0.0.0.255 10.40.10.0 0.0.0.255 » refuse les invités vers l’administration ; une ligne « permit ip any any » devra suivre, car une ACL se termine par un refus implicite.'),
  ('98606d62-2115-49c9-8985-4ce7899bb8c5', array['gi0/0.30 in', 'g0/0.30 in', 'gigabitethernet0/0.30 in', 'interface gi0/0.30 in', 'gi0/0.30 entrant', 'gigabitethernet0/0.30 entrant', 'gigabitethernet 0/0.30 in']::text[], 'Appliquée en entrée (in) sur Gi0/0.30, l’ACL filtre le trafic dès qu’il arrive des invités, avant qu’il soit routé : c’est la règle « étendue au plus près de la source ».'),
  ('6c9b5a8f-96dc-3eb8-1799-1acf610e892c', array['99']::text[], 'Le VLAN 99 (Gestion) n’a aucun port d’accès : il sert aux adresses d’administration des équipements. Rapprocher le plan documenté de la configuration observée est un réflexe de documentation.'),
  ('c3d0ee7c-0986-bcb8-1fe1-309b2d1cc237', array['2']::text[], 'Un /30 contient 4 adresses : l’adresse réseau, l’adresse de diffusion et 2 adresses utilisables, une par routeur. C’est le plus petit réseau pratique pour une liaison point à point.'),
  ('3f6a120e-5ac5-cd11-82d2-f9d475ead8c8', array['172.20.0.7']::text[], 'Le bloc 172.20.0.4/30 va de 172.20.0.4 à 172.20.0.7. La dernière adresse est la diffusion : seules les deux adresses du milieu sont attribuables.'),
  ('adfee18e-a9df-2e4e-a41a-b314c8bdf8ce', array['ip route 10.60.5.0 255.255.255.0 172.20.0.1']::text[], 'R-Nord ne connaît que le siège : il lui envoie tout ce qui vise l’agence Sud. « ip route 10.60.5.0 255.255.255.0 172.20.0.1 » désigne le réseau de l’agence Sud et, comme prochain saut, l’adresse de R-Siege sur la liaison Nord.'),
  ('7b489190-3b44-ffb1-d490-03a5ef759c33', array['ip route 0.0.0.0 0.0.0.0 172.20.0.5']::text[], 'La route par défaut « ip route 0.0.0.0 0.0.0.0 172.20.0.5 » envoie tout le trafic inconnu vers le siège. C’est la solution la plus simple pour une agence qui n’a qu’une sortie.'),
  ('4cec5d26-3d1a-30a5-9273-3120cd944b0a', array['10.60.5.0/24', '10.60.5.0']::text[], 'R-Siege connaît le réseau de l’agence Nord (route S) mais pas 10.60.5.0/24. C’est pourquoi le ping vers l’agence Sud échoue : le routeur n’a aucune route pour cette destination.'),
  ('5583233a-4c87-ab8d-78da-733c2e2ac159', array['ip route 10.60.5.0 255.255.255.0 172.20.0.6']::text[], '« ip route 10.60.5.0 255.255.255.0 172.20.0.6 » indique à R-Siege que le réseau de l’agence Sud est atteignable via R-Sud, côté liaison Sud. Après cette commande, show ip route affichera une seconde route S.'),
  ('3f87868f-b71e-1a2d-0550-69d353bfe8d8', array['10.60.4.0/23']::text[], 'Les deux /24 voisins (10.60.4.0/24 et 10.60.5.0/24) tiennent dans 10.60.4.0/23. Un résumé réduit la taille des tables de routage, à condition que tout le bloc résumé soit bien joignable par ce chemin.'),
  ('5c25e314-20ca-7064-d19a-09f50cfaadd3', array['s', 's (static)', 'static']::text[], 'Dans la légende de show ip route, S désigne une route statique, C une route directement connectée et L l’adresse locale d’une interface.'),
  ('23a97b41-0e0d-2383-b152-36720f3de75e', array['1']::text[], 'Dans [1/0], le premier nombre est la distance administrative (1 pour une route statique) et le second la métrique. Une distance faible signifie une source de confiance : une route statique l’emporte sur une route RIP ou OSPF.'),
  ('157220bf-4340-9599-8a02-da7c474888a7', array['non', 'no']::text[], 'Non : la route par défaut envoie le paquet vers le siège, qui connaît le chemin. Une route spécifique n’est utile que pour choisir un autre chemin que la route par défaut.'),
  ('784bec19-1d98-0d3e-04e4-31ac5e0218ec', array['10.40.20.254']::text[], 'PC-Compta utilise 10.40.20.254, une adresse qui n’existe pas : la passerelle du VLAN 20 est 10.40.20.1. Le poste joint son propre réseau mais ne peut rien joindre au-delà.'),
  ('b06d83d7-804b-dbee-c5e2-188f38cd60e0', array['passerelle', 'mauvaise passerelle', 'passerelle erronée', 'passerelle erronee', 'passerelle par défaut', 'passerelle par defaut', 'gateway', 'la passerelle']::text[], 'La passerelle configurée (10.40.20.254) n’existe pas. Le poste n’arrive pas à la joindre et affiche « Impossible de joindre l’hôte de destination » en répondant depuis sa propre adresse : c’est la signature d’une passerelle injoignable.'),
  ('690a4071-ce8c-4d8b-c6ee-83be8bc6d761', array['3', 'couche 3', 'réseau', 'reseau', 'couche réseau', 'couche reseau', 'layer 3']::text[], 'Une adresse de passerelle est une adresse IP : le défaut se situe à la couche 3, la couche réseau. Un défaut de câble serait en couche 1, un défaut de VLAN en couche 2.'),
  ('4e3894fc-de10-0900-e1fb-55dc78b2c73a', array['fa0/12', 'fastethernet0/12', 'fastethernet 0/12', 'f0/12', 'fa 0/12']::text[], 'La table MAC associe 0090.2b7a.31d5 au port Fa0/12. Une adresse MAC se retrouve d’un format à l’autre : 00-90-2B-7A-31-D5 devient 0090.2b7a.31d5.'),
  ('e5968c5d-c0c4-a584-7a55-187e9ba88efe', array['1', 'vlan 1']::text[], 'Le port Fa0/12 est resté dans le VLAN 1, le VLAN par défaut, où aucun service DHCP n’écoute. Le poste s’attribue alors une adresse automatique en 169.254.x.x.'),
  ('73af7247-41d7-171a-11a2-6329344999f0', array['switchport access vlan 20']::text[], '« switchport access vlan 20 » affecte le port d’accès au VLAN 20. Le poste recevra alors une adresse du service DHCP de son VLAN.'),
  ('7eb6c68d-736f-7491-d385-1fbe5b755708', array['30', 'vlan 30']::text[], 'Le VLAN 30 (Invités) existe sur SW1 mais n’est pas autorisé sur le trunk : ses trames n’atteignent jamais le routeur. Les autres VLAN fonctionnent, ce qui isole la panne.'),
  ('09ca62e8-0b5f-630e-34b1-a83b93dc9e86', array['switchport trunk allowed vlan add 30']::text[], '« switchport trunk allowed vlan add 30 » ajoute le VLAN 30 à la liste. Sans « add », la commande remplacerait la liste entière et couperait tous les autres VLAN.'),
  ('d31d383c-de6d-86a1-9e07-25ff9eac5c2c', array['deny ip 10.40.20.0 0.0.0.255 host 10.40.10.10', '10 deny ip 10.40.20.0 0.0.0.255 host 10.40.10.10']::text[], 'La ligne « 10 deny ip 10.40.20.0 0.0.0.255 host 10.40.10.10 » refuse tout le VLAN 20 vers le serveur : c’est un blocage trop large pour un serveur que la comptabilité doit joindre. Ses compteurs montrent qu’elle intercepte vraiment le trafic.'),
  ('401ed52d-ee46-b9df-3b1e-cd856a60be64', array['12']::text[], 'Le compteur affiche 12 correspondances : chaque tentative de la comptabilité vers FS01 a été refusée. Un compteur qui monte pendant un test prouve qu’une règle agit.'),
  ('bdde2d0c-a757-efd2-1a33-5885714647fa', array['no 10']::text[], '« no 10 » supprime la ligne de séquence 10 sans toucher aux autres. Il faut ensuite refaire le test, puis vérifier que les règles voulues sont bien présentes.'),
  ('0cdc681b-6e9f-d4d6-91e7-aacb793fdff8', array['7', '7 minutes', '7 min']::text[], 'Le routeur indique 09:41 et le commutateur 09:34 pour le même événement : 7 minutes d’écart. Corréler ces journaux sans corriger ce décalage mènerait à de fausses conclusions.'),
  ('ce36dcdd-4cbd-b02d-adb2-03b4d7300450', array['ntp', 'network time protocol']::text[], 'NTP aligne l’horloge de chaque équipement sur un serveur de temps. Sans lui, les journaux ne se corrèlent pas : les équipements affichent un astérisque devant l’heure quand leur horloge n’est pas synchronisée.'),
  ('e212805f-5aac-43d7-dea7-0a410de7df80', array['/25', '25']::text[], 'Un /25 offre 126 adresses utilisables : assez pour 110, alors qu’un /26 n’en offre que 62.'),
  ('863a908d-c006-b30d-889b-105b698ae8d8', array['10.80.0.128']::text[], 'Employés occupe le début du bloc ; Administration (45 adresses, donc un /26) commence juste après : 10.80.0.128.'),
  ('ca61eb9b-292c-dc02-c7c4-a9d5e03c3a79', array['10.80.0.223']::text[], 'Le sous-réseau Invités est un /27 de 32 adresses qui suit Administration. Sa dernière adresse, 10.80.0.223, est la diffusion.'),
  ('9b96f7bb-d210-3966-fc44-1790e0b252e3', array['10.80.0.225']::text[], 'Serveurs est un /28 de 16 adresses. Sa première adresse utilisable est 10.80.0.225 : c’est la passerelle du VLAN, selon la règle du cahier des charges.'),
  ('237ed1f1-36b9-f124-71f6-55bdff2af82a', array['255.255.255.248']::text[], 'Pour 5 adresses utilisables, il faut un /29 (6 utilisables), soit le masque 255.255.255.248. Un /30 n’en offrirait que 2.'),
  ('3b67ad37-6b05-3366-48b2-ce5fc4d440f4', array['10.80.0.248']::text[], 'Les cinq sous-réseaux occupent le début du bloc sans trou. La première adresse libre est 10.80.0.248 : tout le reste de 10.80.0.0/22 est disponible pour la croissance.'),
  ('f3be1e9d-6a10-0c0e-9235-4ffb4372c866', array['32']::text[], 'Un 10.80.0.0/22 compte 1 024 adresses et un /27 en compte 32 : le bloc contient 32 sous-réseaux /27.'),
  ('91e791b8-584f-3b13-6011-4e369067e013', array['65536', '65 536']::text[], 'Entre /48 et /64, il y a 16 bits pour numéroter les sous-réseaux : 2 puissance 16, soit 65536 sous-réseaux /64.'),
  ('097cdb2f-455b-3dd0-2c75-4c48bd43c790', array['2001:db8:4b00:1e::/64', '2001:db8:4b00:1e::']::text[], 'Le numéro de VLAN 30 vaut 1e en hexadécimal. Le quatrième groupe devient donc 1e : 2001:db8:4b00:1e::/64.'),
  ('94ceef75-9643-14ab-d729-6c4be4dd9965', array['10.80.0.11']::text[], 'Les dix premières adresses utilisables (passerelle comprise) sont exclues du service : la plage commence à 10.80.0.11.'),
  ('94f88e65-38cd-efbc-0b69-fd4894cb3799', array['116']::text[], 'La plage va de 10.80.0.11 à la dernière adresse utilisable du /25 : 116 adresses disponibles pour les postes des employés.'),
  ('2405630b-e46d-4558-43dd-7425e03daa13', array['1', 'une', 'un', '1 adresse', 'une adresse']::text[], 'PAT remplace l’adresse source par une adresse publique et distingue chaque conversation par un numéro de port : une seule adresse publique suffit pour tous les VLAN.'),
  ('292cb78a-64fb-6c19-55b9-b64189a47da5', array['ip route 0.0.0.0 0.0.0.0 192.0.2.1']::text[], '« ip route 0.0.0.0 0.0.0.0 192.0.2.1 » envoie vers l’opérateur tout ce que le routeur ne connaît pas : c’est la sortie Internet de Kora. Le prochain saut est l’adresse de l’opérateur sur le lien, jamais l’adresse de Kora.'),
  ('61b0a2ee-8420-5bb5-ab2b-eeae498731f3', array['6']::text[], 'Un réseau connecté par interface active : 5 sous-réseaux de VLAN et 1 lien opérateur, soit 6 routes C. Chaque interface ajoute aussi une route locale (L, en /32), qui est comptée à part.'),
  ('8ccd570c-840a-749f-52f9-bc7fdadd1489', array['10.80.0.226']::text[], '10.80.0.226 apparaît deux fois, pour deux serveurs : un conflit d’adresse. Un inventaire sans doublon est la première vérification d’une documentation fiable.'),
  ('f93c4f3f-e4ed-3080-4b2f-091f85ba2282', array['ap-invités', 'ap-invites']::text[], 'AP-Invités est déclaré dans le VLAN Invités mais son adresse appartient au sous-réseau Administration : elle ne communiquera pas correctement avec la passerelle de son VLAN.'),
  ('410e4670-46cd-d536-6bcf-74fe972faf08', array['nas-sauvegarde', 'nas']::text[], 'NAS-Sauvegarde n’a pas de passerelle documentée : on ne saura ni lui permettre de sortir de son sous-réseau ni dépanner sa configuration. Une documentation incomplète est une dette technique.')
