  ('2b0b26f9-1b22-5cbe-eb16-9cfd3b42d3df', 'b6587aa3-84f4-9fb1-6b63-7df6a5bf99ef', 'topology', 'Topologie du TP 3', 'Trois routeurs, deux liaisons /30 et un réseau local par site.', '/labs/tp3-topologie.svg', 1),
