  ('1605e38c-1c7e-ca08-0a4d-a60776d91daf', 'f608e920-de51-f74c-f1c8-0af0a9bff9e3', 'log', 'Relevés du ticket 2026-0317 (incident-reseau-kora.log)', 'Trois postes, le routeur R1 et le commutateur SW1 : outputs de ping, ipconfig, show et journaux.', '/labs/incident-reseau-kora.log', 1),
  ('b2db437a-367d-2e0f-2532-7fd5664314d0', '1592d04b-debc-33f8-aa67-bd5d34a00280', 'guide', 'Cahier des charges de Kora', 'Bloc IPv4 et IPv6, besoins par service, services à prévoir et règles de filtrage.', '/labs/projet-kora-cahier-des-charges.md', 1),
  ('421c4445-6b9f-edfa-f6e0-7bf315bac197', '1592d04b-debc-33f8-aa67-bd5d34a00280', 'topology', 'Topologie de référence', 'Le routeur, le commutateur et les cinq VLAN de Kora.', '/labs/projet-kora-topologie.svg', 2),
  ('a947e9a2-6fe6-f55a-2e9f-e78c7de04e8b', '1592d04b-debc-33f8-aa67-bd5d34a00280', 'guide', 'Inventaire existant à vérifier', 'Le plan en vigueur et l’inventaire saisi à la main, avec ses incohérences.', '/labs/projet-kora-inventaire-a-verifier.md', 3),
