  ('3fe877ca-34cb-6af9-24f6-6d0993f73a72', '0194e939-4b22-ac0f-fd7b-e571c31edc10', 'commutation-vlan', 'VLAN et trunk', 'Segmenter un commutateur en VLAN et lire l’état d’un trunk 802.1Q.', 260),
  ('23545a9d-4a0f-2e52-09fb-fe8a544a3aa0', '0194e939-4b22-ac0f-fd7b-e571c31edc10', 'routage-statique', 'Routage statique', 'Écrire des routes statiques et une route par défaut, lire une table de routage.', 270),
