  ('bbcfe316-3a4c-55f8-93a7-7946ee9e7548', '0194e939-4b22-ac0f-fd7b-e571c31edc10', 'diagnostic-reseau', 'Diagnostic réseau', 'Appliquer une méthode de dépannage et recouper des relevés pour isoler une panne.', 290),
